   217	/**
   218	 * The org's system (Builder) agent id: the explicit `system_agent_id` pointer
   219	 * when set, else the conventional `lobu-builder` row if it exists. Null when the
   220	 * org has no builder (deleted + sentinel), so the caller skips the link.
   221	 */
   222	async function resolveBuilderAgentId(
   223	  organizationId: string,
   224	): Promise<string | null> {
   225	  const rows = (await getDb()`
   226	    SELECT COALESCE(
   227	      o.system_agent_id,
   228	      (SELECT a.id FROM agents a
   229	        WHERE a.organization_id = ${organizationId} AND a.id = ${BUILDER_AGENT_ID}
   230	        LIMIT 1)
   231	    ) AS agent_id
   232	    FROM organization o
   233	    WHERE o.id = ${organizationId}
   234	    LIMIT 1
   235	  `) as Array<{ agent_id: string | null }>;
   236	  return rows[0]?.agent_id ?? null;
   237	}
