   195		const { isAuthenticated } = useAuthState();
   196		const { isMember } = useCurrentOrg();
   197		const canManageWorkspace = isAuthenticated && isMember;
   198		const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
   199			enabled: canManageWorkspace,
   200		});
   201		useSystemAgentId({
   202			enabled: canManageWorkspace,
   203		});
   204	
   205		const selectedAgent = agents.find((a) => a.agentId === agentId) ?? null;
   206		const agentNotFound =
   207			!selectedAgent && !isAgentsLoading && canManageWorkspace;
   208	
   209		const base = `/${owner}/agents/${agentId}`;
   210		const chatPrefix = `${base}/chat`;
   211		const conversationsPrefix = `${base}/conversations`;
   212		const isAgentChat =
   213			pathname === chatPrefix || pathname.startsWith(`${chatPrefix}/`);
   214		// Inbound platform conversations (e.g. a Slack thread) live on their own
   215		// /conversations/$id route — treat them as chat for overflow layout.
   216		const isAgentConversation =
   217			pathname === conversationsPrefix ||
   218			pathname.startsWith(`${conversationsPrefix}/`);
   219		const isChat = isAgentChat || isAgentConversation;
   220		const activeDest = activeConfigDest(base, pathname);
   221		useEffect(() => {
   222			if (agentNotFound) {
   223				void navigate({ to: "/$owner", params: { owner }, replace: true });
   224			}
   225		}, [agentNotFound, navigate, owner]);
