import { Activity, Boxes, type LucideIcon, Plug } from "lucide-react";

/**
 * Owner-scoped nav sections — one icon + label shared by sidebar and page
 * headers. The sidebar is the site map: sections render in this order.
 *
 *  - **Activity** → the Events stream (`/activity`)
 *  - **Connectors** → connectors + synthesized providers/sandboxes
 *  - **Memory** → entity types/records (`/memory`)
 */
export const OWNER_SECTIONS = {
	activity: {
		icon: Activity,
		label: "Activity",
		/** Router template. */
		to: "/$owner/activity",
		search: {} as Record<string, unknown>,
		/** Path segment under `/$owner/` used for matching. */
		segment: "activity",
	},
	connectors: {
		icon: Plug,
		label: "Connectors",
		to: "/$owner/connectors",
		search: {} as Record<string, unknown>,
		segment: "connectors",
	},
	context: {
		icon: Boxes,
		label: "Memory",
		to: "/$owner/memory",
		search: {} as Record<string, unknown>,
		segment: "memory",
	},
} as const satisfies Record<
	string,
	{
		icon: LucideIcon;
		label: string;
		to: string;
		search: Record<string, unknown>;
		segment: string;
	}
>;

export type OwnerSectionKey = keyof typeof OWNER_SECTIONS;

/** Whether a sidebar section is active for the current path. */
export function isOwnerSectionActive(
	key: OwnerSectionKey,
	owner: string,
	pathname: string,
): boolean {
	const base = `/${owner}/${OWNER_SECTIONS[key].segment}`;
	return (
		pathname === base ||
		pathname === `${base}/` ||
		pathname.startsWith(`${base}/`)
	);
}

