	const revoke = useRevokeMcpClient();
	const [confirming, setConfirming] = useState(false);

	const group = useMemo(
		() => groupClients(clients).find((g) => g.clientIds.includes(clientId)),
		[clients, clientId],
	);
	const clientIds = group?.clientIds ?? [];
	const conversationsQuery = useClientActivityScopes({
		enabled: !!group,
		limit: 100,
		clientIds,
		activityKind: "conversation",
	});
	const sessionsQuery = useClientActivityScopes({
		enabled: !!group,
		limit: 100,
		clientIds,
		activityKind: "session",
	});
	const allScopes = useMemo(
		() => [...(conversationsQuery.data ?? []), ...(sessionsQuery.data ?? [])],
		[conversationsQuery.data, sessionsQuery.data],
	);
	const selectedScope = activityId
		? allScopes.find((scope) => scope.activityId === activityId)
		: undefined;
	const visibleKind =
		selectedScope?.activityKind ??
		((conversationsQuery.data?.length ?? 0) > 0 ? "conversation" : "session");
	const visibleScopes = allScopes.filter(
		(scope) => scope.activityKind === visibleKind,
	);
	const eventFilters = useMemo(
		() =>
			group
				? {
						clientIds: group.clientIds,
						mcpActivityId: activityId ?? null,
						sortBy: "date" as const,
						sortOrder: "desc" as const,
					}
				: undefined,
		[group, activityId],
	);
	const eventsQuery = useInfiniteContentWithFilters(
		orgContext.organizationId,
		undefined,
		eventFilters,
		ownerSlug,
	);
	const notificationQuery = useNotifications(group ? orgContext : null, {
		clientIds,
		mcpActivityId: activityId ?? null,
		enabled: !!group,
	});
	const activityEvents = useMemo(
		() =>
			collapseSupersedeChains(
				(eventsQuery.data?.pages ?? []).flatMap((page) => page.content),
			).slice(0, 10),
		[eventsQuery.data],
	);
	const notifications = useMemo(
		() =>
			(notificationQuery.data?.pages ?? []).flatMap(
				(page) => page.notifications,
			),
		[notificationQuery.data],
	);
	// The raw registrations behind the group — each is a separate OAuth grant.
	const registrations = useMemo(
		() => clients.filter((c) => group?.clientIds.includes(c.id)),
		[clients, group],
	);

	if (isLoading) {
		return (
			<ConnectorPageColumn className="space-y-4">
				<div className="flex items-center gap-2">
					<Skeleton className="h-6 w-6 rounded" />
					<Skeleton className="h-5 w-40" />
				</div>
				<Skeleton className="h-24 w-full rounded-lg" />
			</ConnectorPageColumn>
		);
	}

	if (!group) {
		return (
			<ConnectorPageColumn className="space-y-3">
				<p className="text-sm text-muted-foreground">
					This app isn't connected to this workspace, so its details aren't
					available.
				</p>
				<Link
					to="/$owner/connectors"
					params={{ owner: ownerSlug }}
					search={{}}
					className="text-sm text-primary hover:underline"
				>
					Back to connectors
				</Link>
			</ConnectorPageColumn>
		);
	}

	const primary = registrations[0];
	const redirectUris = (primary?.details?.redirectUris ?? []) as string[];
	const memberUrl = group.linkedUserEntitySlug
		? buildMemoryEntityScopePath(ownerSlug, [
				{ entity_type: "$member", slug: group.linkedUserEntitySlug },
			])
		: null;
	const rows: Array<{ label: string; value: ReactNode }> = [
		{ label: "Registered", value: group.title },
		{
			label: group.clientIds.length === 1 ? "Client ID" : "Client IDs",
			value: (
				<div className="space-y-1">
					{group.clientIds.map((id) => (
						<code key={id} className="block break-all">
							{id}
						</code>
					))}
				</div>
			),
		},
		...(group.drivenBy && group.drivenBy !== group.title
			? [{ label: "Driven by", value: group.drivenBy }]
			: []),
		...(primary?.platform
			? [{ label: "Software", value: primary.platform }]
			: []),
		...(redirectUris.length > 0
			? [{ label: "Redirects", value: redirectUris.join(", ") }]
			: []),
		{
			label: "Granted by",
			value:
				memberUrl && group.linkedUser ? (
					<Link
						to={memberUrl as "/"}
						className="font-medium text-primary hover:underline"
					>
						{group.linkedUser}
					</Link>
				) : (
					(group.linkedUser ?? "—")
				),
		},
		{
			label: "Last active",
			value: group.connected ? relativeTime(group.lastSeenAt) : "disconnected",
		},
		{
			label: "Registrations",
			value: String(group.clientIds.length),
		},
	];

	return (
		<div className="flex flex-1 flex-col">
			<ConnectorPageShell
				header={
					<DetailHeader
						breadcrumb={
							<DetailBreadcrumb
								crumbs={[
									<Link
										key="connectors"
										to="/$owner/connectors"
										params={{ owner: ownerSlug }}
										search={{}}
										className={DETAIL_CRUMB_LINK_CLASS}
									>
										Connectors
									</Link>,
								]}
							/>
						}
						icon={
							<span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-md border text-muted-foreground">
								<ClientAppIcon name={group.title} />
							</span>
						}
						title={group.title}
						badge={
							<Badge
								variant={group.connected ? "secondary" : "outline"}
								className="text-[10px]"
							>
								{group.connected ? "Connected" : "Disconnected"}
							</Badge>
						}
						caption={`Connects into this workspace over MCP as ${
							group.linkedUser ?? "a member"
						}, with that person's access.`}
					/>
				}
			>
				<PageSection
					title={visibleKind === "conversation" ? "Conversations" : "Sessions"}
					count={
						visibleScopes.length > 0 ? String(visibleScopes.length) : undefined
					}
					action={
						activityId ? (
							<Link
								to="/$owner/connectors/client/$clientId"
								params={{ owner: ownerSlug, clientId: group.clientId }}
								search={{ activity: undefined }}
								className="text-xs text-primary hover:underline"
							>
								Show all app activity
							</Link>
						) : null
					}
				>
					{conversationsQuery.isLoading || sessionsQuery.isLoading ? (
						<div className="flex items-center py-4 text-xs text-muted-foreground">
							<Spinner className="mr-2" /> Loading client activity…
						</div>
					) : conversationsQuery.isError || sessionsQuery.isError ? (
						<p className="py-3 text-xs text-destructive">
							Could not load this app's activity.
						</p>
					) : visibleScopes.length === 0 ? (
						<p className="py-3 text-xs text-muted-foreground">
							No recent{" "}
							{visibleKind === "conversation" ? "conversations" : "sessions"}.
						</p>
					) : (
						<div className="divide-y overflow-hidden rounded-lg border">
							{visibleScopes.map((scope) => {
								const selected = scope.activityId === activityId;
								return (
									<Link
										key={`${scope.clientId}:${scope.activityId}`}
										to="/$owner/connectors/client/$clientId"
										params={{ owner: ownerSlug, clientId: scope.clientId }}
										search={{ activity: scope.activityId }}
										className={`flex items-center gap-3 px-3 py-2.5 text-xs transition-colors hover:bg-accent/50 ${
											selected ? "bg-accent" : ""
										}`}
									>
										<div className="min-w-0 flex-1">
											<div className="truncate font-medium">
												{scope.title?.trim() ||
													(visibleKind === "conversation"
														? "Untitled conversation"
														: "MCP session")}
											</div>
											<div className="truncate text-muted-foreground">
												{scope.callCount}{" "}
												{scope.callCount === 1 ? "call" : "calls"}
												{" · "}
												{scope.lastAction}
												{" · "}
												{formatTimeAgo(scope.lastCallAt)}
											</div>
										</div>
										{scope.unreadNotificationCount > 0 ? (
											<Badge variant="secondary" className="text-[10px]">
												{scope.unreadNotificationCount} unread
											</Badge>
										) : null}
									</Link>
								);
							})}
						</div>
					)}
				</PageSection>

				<PageSection
					title="Notifications"
					count={
						notifications.length > 0 ? String(notifications.length) : undefined
					}
				>
					{notificationQuery.isLoading ? (
						<div className="flex items-center py-4 text-xs text-muted-foreground">
							<Spinner className="mr-2" /> Loading notifications…
						</div>
					) : notificationQuery.isError ? (
						<p className="py-3 text-xs text-destructive">
							Could not load notifications.
						</p>
					) : notifications.length === 0 ? (
						<p className="py-3 text-xs text-muted-foreground">
							No notifications{" "}
							{activityId ? "from this activity" : "from this app"}.
						</p>
					) : (
						<div className="divide-y overflow-hidden rounded-lg border">
							{notifications.slice(0, 10).map((notification) => (
								<div key={notification.id} className="px-3 py-2.5 text-xs">
									<div className="flex items-baseline justify-between gap-3">
										<span className="font-medium">{notification.title}</span>
