/**
 * A reusable Behavior template from the global catalog (GET /catalog?kinds=behaviors).
 * `detail` mirrors the create-form fields (snake_case) for prefill.
 */
export interface BehaviorCatalogTemplate {
	id: string;
	name: string;
	description?: string | null;
	detail: {
		slug?: string;
		description?: string;
		prompt?: string;
		triggers?: Array<Record<string, unknown>>;
		sources?: Array<{ name: string; query: string }>;
		classifiers?: unknown[];
		outputs?: Record<string, unknown>;
		reactions_guidance?: string;
		reaction_script?: string;
		model_config?: Record<string, unknown>;
		execution_config?: Record<string, unknown>;
		tags?: string[];
	};
}

/**
 * Fetch reusable Behavior templates from the global catalog. Served from the
 * bundled defaults unless `LOBU_CATALOG_URIS` overrides them (env wins outright).
 */
export function useBehaviorCatalog() {
	return useQuery({
		queryKey: ["behavior-catalog"],
		queryFn: async () => {
			const result = await apiCall<{
				catalogs?: { behaviors?: { entries?: BehaviorCatalogTemplate[] } };
			}>("manage_catalog", { action: "list_catalog", kinds: ["behaviors"] });
			return result.catalogs?.behaviors?.entries ?? [];
		},
		staleTime: 60000,
	});
}

/**
 * Fetch Behaviors for an entity. When entityId is undefined, fetch across all
 * entities in the organization.
 */
export function useBehaviorsList(
	organizationId: string | undefined,
	entityId?: number,
	options?: { includeDetails?: boolean },
) {
	return useQuery({
		queryKey: [
			"behaviors-list",
			organizationId,
			entityId,
			options?.includeDetails ?? true,
		],
		queryFn: async () => {
			const result = await apiCall<{ behaviors: BehaviorRecord[] }>(
				"manage_behaviors",
				{
					action: "list",
					entity_id: entityId, // undefined = all entities
					status: "active",
					include_details: options?.includeDetails ?? true,
				},
			);
			return result.behaviors || [];
		},
		// Only requires organizationId - entityId is optional
		enabled: !!organizationId,
		staleTime: 30000,
	});
}

export function useAgentBehaviorsList(
