/**
 * Fetch behavior detail with windows
 */
export function useBehaviorDetail(
	behaviorId: string | undefined,
	entityId: number | undefined,
	organizationId: string | undefined,
	options: {
		since?: string;
		until?: string;
		granularity?: TimeGranularity;
		templateVersion?: number;
		/** Inline edit form sets this to fetch the version dropdown. */
		includeVersions?: boolean;
	} = {},
) {
	return useQuery({
		queryKey: [
			"behavior-detail",
			behaviorId,
			entityId,
			options.since,
			options.until,
			options.granularity,
			options.templateVersion,
			options.includeVersions ?? false,
		],
		queryFn: async () => {
			const result = await apiCall<BehaviorDetailResult>(
				"get_behavior",
				{
					behavior_id: behaviorId,
					entity_id: entityId,
					content_since: options.since,
					content_until: options.until,
					granularity: options.granularity,
					template_version: options.templateVersion,
					page_size: 100,
					include_classification: "summary",
					include_versions: options.includeVersions ?? false,
				},
				undefined,
				{ timeoutMs: 30_000 },
			);
			return result;
		},
		enabled: !!behaviorId && !!organizationId,
		staleTime: 30000,
	});
}

