function CloneBehaviorPicker({
	organizationId,
	onSelect,
}: {
	organizationId: string;
	onSelect: (prefill: {
		name: string;
		slug: string;
		prompt?: string;
		classifiers?: unknown[];
		outputs?: Record<string, unknown>;
	}) => void;
}) {
	const { data: behaviors, isLoading } = useBehaviorsList(organizationId);
	const [search, setSearch] = useState("");

	const filtered = (behaviors || []).filter((w) =>
		w.name?.toLowerCase().includes(search.toLowerCase()),
	);

	if (isLoading) {
		return <TabLoadingState label="behaviors" variant="list-picker" rows={4} />;
	}

	if (!behaviors || behaviors.length === 0) {
		return (
			<p className="text-sm text-muted-foreground py-4">
				No existing behaviors to clone.
			</p>
		);
	}

	return (
		<div className="space-y-3">
			<input
				type="text"
				value={search}
				onChange={(e) => setSearch(e.target.value)}
				placeholder="Search behaviors..."
				className="w-full rounded-md border px-3 py-2 text-sm bg-background"
			/>
			<div className="space-y-2 max-h-[400px] overflow-y-auto">
				{filtered.map((behavior) => (
					<button
						key={behavior.behavior_id}
						type="button"
						onClick={() =>
							onSelect({
								name: `${behavior.name} (copy)`,
								slug: `${behavior.slug || behavior.behavior_id}-copy`,
								prompt: behavior.prompt,
								classifiers: behavior.classifiers,
								outputs: behavior.outputs,
							})
						}
						className="w-full text-left rounded-md border p-3 hover:border-primary/50 hover:bg-primary/5 transition-colors"
					>
						<p className="text-sm font-medium">{behavior.name}</p>
						<p className="text-xs text-muted-foreground mt-1">
							{behavior.entity_name || "Space-level"} · v
							{behavior.version ?? "?"}
						</p>
					</button>
				))}
				{filtered.length === 0 && (
					<p className="text-sm text-muted-foreground text-center py-4">
						No behaviors match your search.
					</p>
				)}
			</div>
		</div>
	);
}
