export interface BehaviorTriggersDraft {
	ready: boolean;
	/** Canonical activation contracts; empty means manual-only. */
	triggers: Array<Record<string, unknown>>;
}

type Slot = {
	key: string;
	/** Seed for the nested editor; stable for the life of the slot. */
	initial: Record<string, unknown> | null | undefined;
};

function newSlotKey(): string {
	return crypto.randomUUID();
}

function slotsFromInitial(
	initialTriggers: Array<Record<string, unknown>> | undefined,
): Slot[] {
	// New form: one blank connector-event draft.
	if (initialTriggers === undefined) {
		return [{ key: newSlotKey(), initial: undefined }];
	}
	// Explicit manual Behavior.
	if (initialTriggers.length === 0) {
		return [{ key: newSlotKey(), initial: null }];
	}
	return initialTriggers.map((trigger) => ({
		key: newSlotKey(),
		initial: trigger,
	}));
}

function isScheduleDraft(draft: BehaviorTriggerDraft | undefined): boolean {
	if (!draft) return false;
	return draft.kind === "time" || draft.trigger?.kind === "schedule";
}

function draftsEqual(
	left: BehaviorTriggerDraft | undefined,
	right: BehaviorTriggerDraft,
): boolean {
	if (!left) return false;
	return (
		left.ready === right.ready &&
		left.kind === right.kind &&
		JSON.stringify(left.trigger) === JSON.stringify(right.trigger)
	);
}

function aggregateDraft(
	slots: Slot[],
	drafts: Record<string, BehaviorTriggerDraft>,
): BehaviorTriggersDraft {
	const ordered = slots.map(
		(slot) =>
			drafts[slot.key] ??
			({
				ready: false,
				kind: "connector_event",
			} satisfies BehaviorTriggerDraft),
	);
	const multi = slots.length > 1;

	if (!multi && ordered[0]?.kind === "manual") {
		return { ready: ordered[0].ready, triggers: [] };
	}

	const scheduleCount = ordered.filter(isScheduleDraft).length;
	const hasManual = ordered.some((draft) => draft.kind === "manual");
	const ready =
		!hasManual &&
		scheduleCount <= 1 &&
		ordered.length > 0 &&
		ordered.every((draft) => draft.ready && draft.trigger);

	return {
		ready,
		triggers: ordered
			.filter((draft) => draft.trigger)
			.map((draft) => draft.trigger as Record<string, unknown>),
	};
}

/**
 * Multi-trigger "When" editor. Each activation is OR'd at runtime; at most one
 * schedule is allowed; an empty list is manual-only. Nested single-trigger
 * editors stay the source of truth for connector/schedule form state.
 */
export function BehaviorTriggersEditor({
	organizationId,
	initialTriggers,
	onChange,
}: {
	organizationId: string | null;
	/**
	 * `undefined` — new Behavior (one blank draft).
	 * `[]` — manual-only.
	 * non-empty — load every stored trigger for edit.
	 */
	initialTriggers?: Array<Record<string, unknown>>;
	onChange: (draft: BehaviorTriggersDraft) => void;
}) {
	const listId = useId();
	const [slots, setSlots] = useState<Slot[]>(() =>
		slotsFromInitial(initialTriggers),
	);
	const [drafts, setDrafts] = useState<Record<string, BehaviorTriggerDraft>>(
		{},
	);
	const lastPublished = useRef<string>("");

	useEffect(() => {
		const next = aggregateDraft(slots, drafts);
		const serialized = JSON.stringify(next);
		if (serialized === lastPublished.current) return;
		lastPublished.current = serialized;
		onChange(next);
	}, [slots, drafts, onChange]);

	const scheduleOwnerKey =
		slots.find((slot) => isScheduleDraft(drafts[slot.key]))?.key ??
		slots.find(
			(slot) =>
				slot.initial &&
				typeof slot.initial === "object" &&
				slot.initial.kind === "schedule" &&
				!drafts[slot.key],
		)?.key ??
		null;

	const handleSlotChange = useCallback(
		(key: string, draft: BehaviorTriggerDraft) => {
			setDrafts((prev) => {
				if (draftsEqual(prev[key], draft)) return prev;
				return { ...prev, [key]: draft };
			});
		},
		[],
	);

	const addTrigger = () => {
		const only = slots[0];
		const onlyDraft = only ? drafts[only.key] : undefined;
		if (
			slots.length === 1 &&
			(onlyDraft?.kind === "manual" || only?.initial === null)
		) {
			const key = newSlotKey();
			setDrafts({});
			setSlots([{ key, initial: undefined }]);
			return;
		}
		setSlots((current) => [
			...current,
			{ key: newSlotKey(), initial: undefined },
		]);
	};

	const removeSlot = (key: string) => {
		if (slots.length <= 1) {
			const nextKey = newSlotKey();
			setDrafts({});
			setSlots([{ key: nextKey, initial: null }]);
			return;
		}
		setDrafts((prev) => {
			const next = { ...prev };
			delete next[key];
			return next;
		});
		setSlots((current) => current.filter((slot) => slot.key !== key));
	};

	return (
		<section className="space-y-4" aria-labelledby={`${listId}-heading`}>
			<div className="space-y-1">
				<h2 id={`${listId}-heading`} className="text-sm font-medium">
					When
				</h2>
				<p className="text-xs text-muted-foreground">
					Each trigger can start this Behavior independently (OR). At most one
					schedule. If several match the same event, the first listed wins for
					run options.
				</p>
			</div>

			<div className="space-y-3">
				{slots.map((slot, index) => {
					const multi = slots.length > 1;
					const kinds: TriggerKind[] = multi
						? scheduleOwnerKey && scheduleOwnerKey !== slot.key
							? ["connector_event"]
							: ["connector_event", "time"]
						: ["connector_event", "time", "manual"];
					const draft = drafts[slot.key];
					const showRemove =
						multi || (draft ? draft.kind !== "manual" : slot.initial !== null);
					return (
						<div
							key={slot.key}
							className={cn(
								"space-y-3 rounded-lg border bg-card/40 p-3",
								multi && "relative",
							)}
						>
							<div className="flex items-center justify-between gap-2">
								<p className="text-xs font-medium text-muted-foreground">
									{multi ? `Trigger ${index + 1}` : "Trigger"}
								</p>
								{showRemove ? (
									<Button
										type="button"
										variant="ghost"
										size="icon"
										className="h-7 w-7 text-muted-foreground hover:text-destructive"
										aria-label={
											multi ? `Remove trigger ${index + 1}` : "Clear trigger"
										}
										onClick={() => removeSlot(slot.key)}
									>
										<Trash2 className="h-3.5 w-3.5" />
									</Button>
								) : null}
							</div>
							<SlotTriggerEditor
								slotKey={slot.key}
								organizationId={organizationId}
								initial={slot.initial}
								kinds={kinds}
								fieldIdPrefix={`${listId}-${slot.key}-`}
								onChange={handleSlotChange}
							/>
						</div>
					);
				})}
			</div>

			<Button
				type="button"
				variant="outline"
				size="sm"
				className="w-full sm:w-auto"
				onClick={addTrigger}
			>
				<Plus className="mr-1.5 h-3.5 w-3.5" />
				Add another trigger
			</Button>
		</section>
	);
}

/** Stable onChange identity per slot so nested editors do not loop. */
function SlotTriggerEditor({
	slotKey,
	organizationId,
	initial,
	kinds,
	fieldIdPrefix,
	onChange,
}: {
	slotKey: string;
	organizationId: string | null;
	initial: Record<string, unknown> | null | undefined;
	kinds: TriggerKind[];
	fieldIdPrefix: string;
	onChange: (key: string, draft: BehaviorTriggerDraft) => void;
}) {
	const handleChange = useCallback(
		(draft: BehaviorTriggerDraft) => onChange(slotKey, draft),
		[onChange, slotKey],
	);
	return (
		<BehaviorTriggerEditor
			organizationId={organizationId}
			initialTrigger={initial}
			allowedKinds={kinds}
			showSectionHeader={false}
			fieldIdPrefix={fieldIdPrefix}
			onChange={handleChange}
		/>
	);
}
