	| "settings";

const CONFIG_MENU: {
	key: AgentConfigDest;
	label: string;
	icon: ComponentType<{ className?: string }>;
	/** Requires org settings admin (write-gate envelope). */
	adminOnly?: boolean;
}[] = [
	{ key: "desk", label: "Desk", icon: Inbox },
