		data: systemAgent,
		isLoading: isSystemAgentLoading,
		error: systemAgentError,
	} = useSystemAgentId();
	const systemAgentId = systemAgent?.systemAgentId ?? null;

	// Auth gate for the whole owner subtree — the chokepoint every
	// `/{owner}/...` page passes through. On a per-org subdomain this is also
	// the landing route: `createSubdomainHistory` rewrites `/` to `/${owner}`
	// before matching, so the `/` route's sign-in redirect never runs there and
	// a signed-out visitor was shown the raw 401 body as a product error.
	// Reuses the workspace query this route's loader already prefetches.
	const {
		data: workspaceRoot,
		isLoading: isWorkspaceLoading,
		error: workspaceError,
	} = useWorkspaceRoot(owner, { slug: owner });
	const { session, isReady: authReady } = useAuthState();
	// A 5xx or transport failure is an outage, not an authz problem; bouncing
	// there would read as "you are not allowed here". Only a refusal — chiefly
	// the 401 a private org answers anonymously — should reach sign-in.
	const isWorkspaceUnavailable =
		isServerError(workspaceError) && !workspaceRoot?.workspace;
	const isRedirectingToSignIn = useAnonymousSignInRedirect({
		active:
			!isWorkspaceLoading &&
			!isWorkspaceUnavailable &&
			authReady &&
			!session &&
			!workspaceRoot?.workspace,
		owner,
	});

	const isHomeView = isOwnerHomePath(owner, pathname);

	// Render nothing while the sign-in navigation lands, so no page in this
	// subtree flashes an auth error on the way to the login screen.
	if (isRedirectingToSignIn) return null;

	if (!isHomeView) {
		return (
			<NotificationPeekProvider>
				<div className="flex min-h-0 flex-1 flex-row">
					{/* `overflow-y-auto`, not `overflow-hidden`: this wrapper is the
					    scroll container for every owner sub-page. The peek pane makes
					    it a flex row, so the shell's outer scroller is clamped to the
					    row height and never sees page overflow — clipping here instead
					    of scrolling made long pages unreachable below the fold. */}
					<div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-y-auto">
						<Outlet />
					</div>
					<NotificationPeekPane />
				</div>
			</NotificationPeekProvider>
		);
	}

	if (isSystemAgentLoading) {
		return (
			<div className="flex min-h-0 flex-1 flex-col gap-3 overflow-hidden py-4 md:py-6">
				<div className="flex shrink-0 flex-col items-center px-4 lg:px-6">
					<AgentWorkbenchHeaderSkeleton />
				</div>
				<div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-hidden px-4 lg:px-6">
					<ChatRoutePendingShell />
				</div>
			</div>
		);
	}

	// Keep load failures distinct from a successful response with no builder.
	if (systemAgentError) {
		return (
			<div className="flex flex-1 flex-col items-center justify-center gap-2 px-4 py-16 text-center">
				<p className="max-w-md text-muted-foreground">
					Couldn't load the workspace builder.
				</p>
				<p className="max-w-md text-sm text-muted-foreground">
					{systemAgentError.message}
				</p>
			</div>
		);
	}

	if (!systemAgentId) {
		return (
			<div className="flex flex-1 flex-col items-center justify-center gap-2 px-4 py-16 text-center">
				<p className="max-w-md text-muted-foreground">
					Workspace builder is not provisioned yet.
				</p>
			</div>
		);
	}
	return (
		<Navigate
			to={agentChatLink(owner, systemAgentId).to}
			params={agentChatLink(owner, systemAgentId).params}
			replace
		/>
	);
}
		document.documentElement.classList.toggle("dark", newIsDark);
		setStored("theme", newIsDark ? "dark" : "light");
	}, [isDark]);

	useEffect(() => {
		const stored = getStored("theme");
		const prefersDark = window.matchMedia(
			"(prefers-color-scheme: dark)",
		).matches;
		const shouldBeDark = stored === "dark" || (!stored && prefersDark);
		setIsDark(shouldBeDark);
		document.documentElement.classList.toggle("dark", shouldBeDark);
	}, []);

	return { isDark, toggle };
}

interface CommandBodyProps {
	search: string;
	onSearchChange: (next: string) => void;
	onClose: () => void;
	inputAtBottom?: boolean;
}

function CommandBody({
	search,
	onSearchChange,
	onClose,
	inputAtBottom = false,
}: CommandBodyProps) {
	const navigate = useNavigate();
	const { isDark, toggle: toggleTheme } = useTheme();
	const { currentOwner, resolvedOrganizationId } = useOrgContext();
	const { session } = useAuthState();
	const { data: systemAgent } = useSystemAgentId({
		enabled: Boolean(currentOwner && session),
	});
	const systemAgentId = systemAgent?.systemAgentId ?? null;

	const debouncedSearch = useDebounce(search.trim(), 200);
	const hasQuery = debouncedSearch.length >= 1;
	const memoryEnabled = debouncedSearch.length >= 3;
	const lowerQ = debouncedSearch.toLowerCase();

	const buildOwnerPath = (path: string): string | null => {
		if (!currentOwner) return null;
		return `/${currentOwner}${path}`;
	};

	const memoryPath = buildOwnerPath("/memory");
	const connectionsPath = buildOwnerPath("/connectors");

	// Entity search.
	//
	// Cancellation: when the debounced query changes the queryKey changes too,
	// so React Query stops observing the stale request — but our queryFns do
	// NOT thread `signal` into fetchWithTimeout, so the stale fetch keeps
	// running on the network until it completes or times out. Acceptable here
	// because (a) the queries are debounced 200ms, (b) results are gated on
	// ≥1 / ≥3 chars, and (c) the underlying endpoints are cheap. If this ever
	// becomes a problem, thread `signal` through useAgents/useConnections/
	// useInfiniteContentWithFilters → apiCall → fetchWithTimeout.
	//
	// Org gating: connectors and memory queries require a resolved org UUID
	// (not just a slug). On a `/<owner>/...` URL where the URL org is not the
	// currently-active org, `resolvedOrganizationId` is null and these groups
	// silently return no results. The agents query is slug-based via
	// `useAgents()` (reads scope from URL path) so it works in both cases.
	// Fixing the cross-org case requires changing the API hooks to accept a
	// slug fallback; out of scope for this PR.
	const { data: agents = [] } = useAgents({
		enabled: hasQuery && !!currentOwner,
	});
	const { data: connections = [] } = useConnections(
		hasQuery ? resolvedOrganizationId : null,
	);
	const memoryQuery = useInfiniteContentWithFilters(
		memoryEnabled ? resolvedOrganizationId : undefined,
		undefined,
		memoryEnabled ? { searchQuery: debouncedSearch } : undefined,
		memoryEnabled ? (currentOwner ?? undefined) : undefined,
	);

	const filteredAgents = useMemo(() => {
		if (!hasQuery) return [];
		return agents
			.filter((a) => a.name.toLowerCase().includes(lowerQ))
			.slice(0, 5);
	}, [agents, hasQuery, lowerQ]);

	const filteredConnections = useMemo(() => {
		if (!hasQuery) return [];
		return connections
			.filter((c) => {
				const label = (
					c.display_name ??
					c.connector_name ??
					c.connector_key ??
					""
				).toLowerCase();
				return label.includes(lowerQ);
			})
			.slice(0, 5);
	}, [connections, hasQuery, lowerQ]);

	const memoryResults = useMemo(() => {
		if (!memoryEnabled) return [];
		return (memoryQuery.data?.pages ?? [])
			.flatMap((p) => p.content ?? [])
			.slice(0, 5);
	}, [memoryEnabled, memoryQuery.data]);

	const runCommand = useCallback(
		(command: () => void | Promise<void>) => {
			onClose();
			Promise.resolve(command()).catch(console.error);
		},
		[onClose],
	);

	// SEVERE codex#2: keep DOM order input-then-list (cmdk requires the input
	// to come before the list for keyboard semantics + autofocus). Visually
	// swap them with flex `order-*` when inputAtBottom is true — the parent
	// <Command> is a `flex flex-col` in the narrow case so the swap takes
	// effect; in the wide CommandDialog the parent isn't a flex column, so
	// `order` is a no-op and the natural DOM order wins.
	const input = (
		<CommandInput
			placeholder="Type a command or search..."
			value={search}
			onValueChange={onSearchChange}
			className={inputAtBottom ? "order-2" : undefined}
		/>
	);

	const list = (
		<CommandList className={inputAtBottom ? "order-1 flex-1" : undefined}>
			<CommandEmpty>No results found.</CommandEmpty>

			{currentOwner && systemAgentId && debouncedSearch.length > 0 && (
				<CommandGroup heading="Ask">
					<CommandItem
						// value === the live query so cmdk always keeps this item (and
						// ranks it first) no matter what was typed → Enter starts a new
						// conversation seeded with the query.
						value={search}
						onSelect={() =>
							runCommand(() => {
								const id = newThreadId();
								setPendingSeed(id, debouncedSearch);
								navigate(agentThreadLink(currentOwner, systemAgentId, id));
							})
						}
					>
						<SquarePen className="mr-2 h-4 w-4 shrink-0" />
						<span className="flex-1 truncate">
							Ask the builder: “{debouncedSearch}”
						</span>
						<CommandShortcut>↵</CommandShortcut>
					</CommandItem>
				</CommandGroup>
			)}

			<CommandGroup heading="Navigation">
				{currentOwner && (
					<CommandItem
						value="new conversation chat thread"
						onSelect={() =>
							runCommand(() =>
								navigate({
									to: "/$owner",
									params: { owner: currentOwner },
									search: { new: true },
								}),
							)
						}

