export function AppSidebar({
	embedded = false,
	collapsed = false,
	onToggleCollapsed,
}: {
	embedded?: boolean;
	collapsed?: boolean;
	onToggleCollapsed?: () => void;
}) {
	const { agentId = null } = useParams({
		strict: false,
	}) as {
		agentId?: string;
	};
	const { pathname, search } = useLocation();
	const searchRecord = (search ?? {}) as Record<string, unknown>;
	const { currentOwner } = useOrgContext();
	const owner =
		currentOwner && !currentOwner.startsWith("@") ? currentOwner : null;
	// The Builder (system agent) is shown FIRST in the Agents roster (via
	// rosterAgents). Click an agent → chat; expand for configuration destinations.
	const { rosterAgents, systemAgentId, isLoading } = useWorkingAgents();

	// "New agent" links straight to the builder chat with a prompt (see helpers
	// — the /$owner redirect would drop search params).
	const newAgent = newAgentLink({ owner, systemAgentId });
	// Collapsed icon-rail — only on the wide fixed sidebar (never embedded in the
	// narrow drawer, which is already a compact off-canvas panel).
	const isRail = collapsed && !embedded;

	if (isRail) {
		return (
			<aside className="fixed inset-y-0 left-0 z-40 flex w-14 flex-col items-center border-r border-border bg-sidebar-background text-sidebar-foreground">
				<div className="flex h-14 w-full items-center justify-center border-b border-sidebar-border">
					<button
						type="button"
						onClick={onToggleCollapsed}
						aria-label="Expand sidebar"
						title="Expand sidebar"
						className="flex h-9 w-9 items-center justify-center rounded-md text-sidebar-foreground/70 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
					>
						<PanelLeftOpen className="h-[18px] w-[18px]" />
					</button>
				</div>
				{owner ? (
					<div className="flex flex-1 flex-col gap-1 overflow-y-auto py-2">
						<RailButton
							label="Search"
							icon={Search}
							onClick={openCommandPalette}
						/>
						{(Object.keys(OWNER_SECTIONS) as OwnerSectionKey[]).map((key) => {
							const section = OWNER_SECTIONS[key];
							return (
								<RailButton
									key={key}
									label={section.label}
									active={isOwnerSectionActive(key, owner, pathname)}
									icon={section.icon}
									to={section.to}
									params={{ owner }}
									search={section.search}
								/>
							);
						})}
					</div>
				) : (
					<div className="flex-1" />
				)}
			</aside>
		);
	}

	return (
		<aside
			className={cn(
				"flex flex-col border-r border-border bg-sidebar-background text-sidebar-foreground",
				embedded ? "h-full w-full" : "fixed inset-y-0 left-0 z-40 w-[17.25rem]",
			)}
		>
			<div className="flex h-14 items-center gap-1 border-b border-sidebar-border px-2">
				<div className="min-w-0 flex-1">
					<OrganizationDropdown />
				</div>
				<button
					type="button"
					onClick={openCommandPalette}
					aria-label="Search"
					title="Search (⌘K)"
					className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-sidebar-foreground/60 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
				>
					<Search className="h-[18px] w-[18px]" />
				</button>
