import {
	type AgentItem,
	useAgents,
	useResolvedPath,
	useSystemAgentId,
} from "@/lib/api";
import { useAuthState } from "@/lib/auth-state";
import { cn } from "@/lib/utils";

/** Agent surfaces under the centered section dropdown. */
type AgentConfigDest =
	| "desk"
	| "behaviors"
	| "skills"
	| "guardrails"
	| "permissions"
	| "models"
	| "settings";

type AgentConfigMenuItem = WorkbenchSection<AgentConfigDest> & {
	/** Requires org settings admin (write-gate envelope). */
	adminOnly?: boolean;
};

const CONFIG_MENU: AgentConfigMenuItem[] = [
	{ key: "desk", label: "Desk", icon: Inbox },
	{ key: "behaviors", label: "Behaviors", icon: ListChecks },
	{ key: "skills", label: "Skills", icon: Sparkles },
	{ key: "guardrails", label: "Guardrails", icon: Shield },
	{ key: "permissions", label: "Permissions", icon: Lock, adminOnly: true },
	{ key: "models", label: "Models", icon: Cpu },
	{ key: "settings", label: "Settings", icon: SettingsIcon },
];

/** Menu rows visible for the current role. Exported for unit tests. */
export function filterConfigMenu(isAdmin: boolean) {
	return CONFIG_MENU.filter((item) => !item.adminOnly || isAdmin);
}

/** Active configure destination for the pathname, or null on chat/conversations. */
function activeConfigDest(
	base: string,
	pathname: string,
): AgentConfigDest | null {
	if (
		pathname === `${base}/chat` ||
		pathname.startsWith(`${base}/chat/`) ||
		pathname === `${base}/conversations` ||
		pathname.startsWith(`${base}/conversations/`)
	) {
		return "desk";
	}
	for (const { key } of CONFIG_MENU) {
		if (key === "desk") continue;
		if (
			pathname === `${base}/${key}` ||
			pathname.startsWith(`${base}/${key}/`)
		) {
			return key;
		}
	}
	// Legacy /identity URLs still resolve; identity fields live on Settings.
	if (pathname === `${base}/identity` || pathname === `${base}/identity/`) {
		return "settings";
	}
	return null;
}

function agentInitial(name: string): string {
	return name.trim().charAt(0).toUpperCase() || "?";
}

/** Centered agent name + section dropdown (Desk, Behaviors, Skills, …). */
function AgentWorkbenchHeader({
	owner,
	agentId,
	agentName,
	activeDest,
}: {
	owner: string;
	agentId: string;
	agentName: string;
	activeDest: AgentConfigDest | null;
}) {
	const navigate = useNavigate();
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	const chat = agentChatLink(owner, agentId);
	const items = filterConfigMenu(!!isAdmin);
	const activeSection = activeDest ?? "desk";
	const activeItem = CONFIG_MENU.find((item) => item.key === activeSection);

	return (
		<WorkbenchHeader
			identity={
				<Link
					to={chat.to}
					params={chat.params}
					className="flex min-w-0 items-center gap-2 rounded-md outline-none transition-colors hover:opacity-90 focus-visible:ring-2 focus-visible:ring-ring"
					title="Back to chat"
				>
					<span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-semibold text-foreground">
						{agentInitial(agentName)}
					</span>
					<h1 className="min-w-0 truncate text-base font-semibold tracking-tight">
						{agentName}
					</h1>
				</Link>
			}
			sections={items}
			activeSection={activeSection}
			activeItem={activeItem}
			sectionLabel="Agent section"
			highlightSection={activeDest !== null}
			onSectionSelect={(key) => {
				if (key === "desk") {
					void navigate({ to: chat.to, params: chat.params });
					return;
				}
				void navigate({
					to: `/$owner/agents/$agentId/${key}`,
					params: { owner, agentId },
				});
			}}
		/>
	);
}

export function AgentsWorkbenchLayout({
	owner,
	agentId,
}: {
	owner: string;
	agentId: string;
}) {
	const navigate = useNavigate();
	const { pathname } = useLocation();
	const { isAuthenticated } = useAuthState();
	const { isMember } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: canManageWorkspace,
	});
	useSystemAgentId({
		enabled: canManageWorkspace,
	});

	const selectedAgent = agents.find((a) => a.agentId === agentId) ?? null;
	const agentNotFound =
		!selectedAgent && !isAgentsLoading && canManageWorkspace;

	const base = `/${owner}/agents/${agentId}`;
	const chatPrefix = `${base}/chat`;
	const conversationsPrefix = `${base}/conversations`;
	const isAgentChat =
		pathname === chatPrefix || pathname.startsWith(`${chatPrefix}/`);
	// Inbound platform conversations (e.g. a Slack thread) live on their own
	// /conversations/$id route — treat them as chat for overflow layout.
	const isAgentConversation =
		pathname === conversationsPrefix ||
		pathname.startsWith(`${conversationsPrefix}/`);
	const isChat = isAgentChat || isAgentConversation;
	const activeDest = activeConfigDest(base, pathname);
	useEffect(() => {
		if (agentNotFound) {
			void navigate({ to: "/$owner", params: { owner }, replace: true });
		}
	}, [agentNotFound, navigate, owner]);

	const agentName = selectedAgent?.name ?? "Agent";

	return (
		<div className="flex min-h-0 flex-1 flex-col gap-3 overflow-hidden py-4 md:py-6">
			{/* Sidebar is the agent picker (→ Desk). Agent destinations live
			    in the centered header dropdown so the roster stays flat. */}
			<AgentWorkbenchHeader
				owner={owner}
				agentId={agentId}
				agentName={agentName}
				activeDest={activeDest}
			/>
			<div
				className={cn(
					"flex min-h-0 min-w-0 flex-1 flex-col px-4 lg:px-6",
					isChat ? "overflow-hidden" : "overflow-y-auto",
				)}
			>
				<Outlet />
			</div>
		</div>
	);
}

export function AgentConfigPane({
	agent,
	tab,
	runId,
}: {
	agent: AgentItem;
	tab: AgentSection;
	/** Slack config-approval deep link `?run_id`; when set, the ProposalReviewShell
	 *  fetches the held builder proposal and the form prefills it for review. */
	runId?: number;
}) {
	return (
		<div className="mx-auto w-full max-w-3xl pb-6">
			<ProposalReviewShell
				resource={{ kind: "agent", agentId: agent.agentId }}
				runId={runId}
			>
				{({ reviewMode, proposal, controlsDisabled }) => (
					<AgentEditorForm
						key={agent.agentId}
						mode={{ kind: "edit", agent }}
						section={tab}
						reviewMode={reviewMode}
						reviewProposal={proposal}
						reviewControlsDisabled={controlsDisabled}
					/>
				)}
			</ProposalReviewShell>
		</div>
	);
}

