export type WorkbenchSection<Key extends string> = {
	key: Key;
	label: string;
	icon: ComponentType<{ className?: string }>;
};

/** Shared identity and section switcher for agent-shaped workspaces. */
export function WorkbenchHeader<Key extends string>({
	identity,
	sections,
	activeSection,
	activeItem,
	onSectionSelect,
	sectionLabel,
	highlightSection = true,
	className,
}: {
	identity: ReactNode;
	sections: ReadonlyArray<WorkbenchSection<Key>>;
	activeSection: Key;
	activeItem?: WorkbenchSection<Key>;
	onSectionSelect: (section: Key) => void;
	sectionLabel: string;
	highlightSection?: boolean;
	className?: string;
}) {
	const displayedItem =
		activeItem ??
		sections.find((section) => section.key === activeSection) ?? sections[0];
	if (!displayedItem) return null;
	const ActiveIcon = displayedItem.icon;

	return (
		<div
			className={cn(
				"flex shrink-0 flex-col items-center px-4 lg:px-6",
				className,
			)}
		>
			<div className="flex min-w-0 max-w-full flex-wrap items-center justify-center gap-x-3 gap-y-2">
				{identity}

				<DropdownMenu>
					<DropdownMenuTrigger asChild>
						<button
							type="button"
							className={cn(
								"inline-flex shrink-0 items-center gap-1.5 rounded-md px-2.5 py-1 text-sm transition-colors outline-none focus-visible:ring-2 focus-visible:ring-ring",
								highlightSection
									? "bg-muted font-medium text-foreground"
									: "text-muted-foreground hover:bg-muted/60 hover:text-foreground",
							)}
							aria-label={sectionLabel}
						>
							<ActiveIcon className="h-3.5 w-3.5 shrink-0" />
							{displayedItem.label}
							<ChevronDown className="h-3.5 w-3.5 shrink-0 opacity-60" />
						</button>
					</DropdownMenuTrigger>
					<DropdownMenuContent align="center" className="min-w-[11rem]">
						{sections.map(({ key, label, icon: Icon }) => (
							<DropdownMenuItem
								key={key}
								className={cn(key === activeSection && "bg-accent font-medium")}
								onSelect={() => onSectionSelect(key)}
							>
								<Icon className="h-4 w-4" />
								<span>{label}</span>
							</DropdownMenuItem>
						))}
					</DropdownMenuContent>
				</DropdownMenu>
			</div>
		</div>
	);
}

