	ownerSlug,
	active,
	searchRecord,
}: {
	ownerSlug: string;
	active: boolean;
	searchRecord: Record<string, unknown>;
}) {
	const section = OWNER_SECTIONS.context;
	const { open, setOpen } = useRouteDefaultOpen(active);
	const { orgContext } = useOrgContext();
	const { data: entityTypes = [] } = useEntityTypes(orgContext);
	// Same org scoping as `useVisibleEntityTypes`, without its system-type filter.
	const visible = useMemo(
		() =>
			entityTypes.filter(
				(et) => !et.organization_slug || et.organization_slug === ownerSlug,
			),
		[entityTypes, ownerSlug],
	);
	// The scoped type currently being browsed, so its row takes the highlight
	// instead of the parent Context row. Two scope keys can name a type:
	// `type` when browsing the list, and `entity` (`<type>/<id>`) after
	// drilling into one record — the type stays highlighted for both.
	const activeTypeSlug =
		typeof searchRecord.type === "string"
			? searchRecord.type
			: typeof searchRecord.entity === "string"
				? searchRecord.entity.split("/")[0]
				: undefined;

	// The row keeps the highlight while the map itself is what is open; once a
	// child type is being browsed, the type's own row carries it instead.
	const isHighlighted = active && !(open && activeTypeSlug);

	return (
		<Collapsible open={open} onOpenChange={setOpen}>
			<div
				className={cn(
					"mx-2 flex items-center gap-2 rounded-md py-1.5 pl-3 pr-2 text-sm transition-colors",
					isHighlighted
						? "bg-sidebar-accent text-sidebar-accent-foreground"
						: "text-sidebar-foreground/80 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground",
				)}
			>
				<Link
					to={section.to}
					params={{ owner: ownerSlug }}
					search={section.search as never}
					className="flex min-w-0 flex-1 items-center gap-2"
				>
					<span className="flex h-3.5 w-3.5 shrink-0 items-center justify-center text-sidebar-foreground/60">
						<section.icon className="h-3.5 w-3.5" />
					</span>
					{/* Expanded, this row is the parent of the type rows beneath it, but
					    it carried their exact weight and indent — so browsing a type,
					    which drops the highlight, left "Memory" reading as one more
					    entity type. Recede it while it has children on screen. The
					    highlight still wins: when the map itself is what is open, being
					    the current page matters more than being a parent. */}
					<span
						className={cn(
							"min-w-0 flex-1 truncate",
							open && !isHighlighted && "text-sidebar-foreground/50",
						)}
					>
						{section.label}
					</span>
				</Link>
				{/* No types yet ⇒ nothing to expand, so the chevron would be a
				    control that does nothing. The row still links to the map. */}
				{visible.length > 0 ? (
					<CollapsibleTrigger asChild>
						<button
							type="button"
							aria-label={
								open ? "Collapse entity types" : "Expand entity types"
							}
							title={open ? "Collapse entity types" : "Expand entity types"}
							className="shrink-0"
						>
							<GroupChevron open={open} />
						</button>
					</CollapsibleTrigger>
				) : null}
			</div>
			<CollapsibleContent>
				{visible.map((entityType) => {
					const link = memoryBrowseTypeSearch(ownerSlug, entityType.slug);
					return (
						<NavRow
							key={entityType.slug}
							to={link.to}
							params={link.params}
							search={link.search}
							active={activeTypeSlug === entityType.slug}
							leading={
								<EntityIcon icon={entityType.icon} className="h-3.5 w-3.5" />
							}
							label={entityType.name || entityType.slug}
							trailing={<EntityCount count={entityType.entity_count ?? 0} />}
						/>
					);
				})}
			</CollapsibleContent>
		</Collapsible>
	);
}

/**
 * One agent in the roster. The row is a single chat link — Behaviors and
 * Configure live in the agent workbench header (agent name + tabs), not as
 * accordion children here.
 */
function AgentRow({
	ownerSlug,
	agentId,
	name,
	status,
	selected,
}: {
	ownerSlug: string;
	agentId: string;
	name: string;
	status: "active" | "idle";
	selected: boolean;
}) {
	const working = status === "active";
	const chat = agentChatLink(ownerSlug, agentId);

	return (
		<Link
			to={chat.to}
			params={chat.params}
			className={cn(
				"mx-2 flex items-center gap-2 rounded-md py-1.5 pl-3 pr-3 text-sm transition-colors",
				selected
					? "bg-sidebar-accent text-sidebar-accent-foreground"
					: "text-sidebar-foreground/80 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground",
			)}
		>
			<AgentAvatar name={name} status={status} />
			<span className="min-w-0 flex-1 truncate">{name}</span>
			{working ? (
				<span className="shrink-0 text-[10px] text-sidebar-foreground/40">
					working
				</span>
			) : null}
		</Link>
	);
}

