/** Icon-only nav button for the collapsed rail. */
function RailButton({
	label,
	active = false,
	icon: Icon,
	onClick,
	to,
	params,
	search,
}: {
	label: string;
	active?: boolean;
	icon: IconComponent;
	onClick?: () => void;
	to?: string;
	params?: Record<string, string>;
	search?: Record<string, unknown>;
}) {
	const className = cn(
		"mx-auto flex h-9 w-9 items-center justify-center rounded-md transition-colors",
		active
			? "bg-sidebar-accent text-sidebar-accent-foreground"
			: "text-sidebar-foreground/70 hover:bg-sidebar-accent/60 hover:text-sidebar-foreground",
	);
	if (to) {
		return (
			<Link
				to={to as "/"}
				params={params as never}
				search={search as never}
				aria-label={label}
				title={label}
				className={className}
			>
				<Icon className="h-[18px] w-[18px]" />
			</Link>
		);
	}
	return (
		<button
			type="button"
			onClick={onClick}
			aria-label={label}
			title={label}
			className={className}
		>
			<Icon className="h-[18px] w-[18px]" />
		</button>
	);
}

export function AppSidebar({
	embedded = false,
	collapsed = false,
	onToggleCollapsed,
}: {
	embedded?: boolean;
	collapsed?: boolean;
	onToggleCollapsed?: () => void;
}) {
	const {
		agentId = null,
		threadId = null,
		conversationId = null,
		behaviorId = null,
		clientId = null,
	} = useParams({
		strict: false,
	}) as {
		agentId?: string;
		threadId?: string;
		conversationId?: string;
		behaviorId?: string;
		clientId?: string;
	};
	const { pathname, search } = useLocation();
	const searchRecord = (search ?? {}) as Record<string, unknown>;
	const { currentOwner } = useOrgContext();
	const owner =
		currentOwner && !currentOwner.startsWith("@") ? currentOwner : null;
	// The Builder (system agent) is shown FIRST in the Agents roster (via
	// rosterAgents). Click an agent → chat; expand for configuration destinations.
	const { rosterAgents, systemAgentId, isLoading } = useWorkingAgents();
	const rosterAgentIds = useMemo(
		() => rosterAgents.map((agent) => agent.agentId),
		[rosterAgents],
	);
	const { threads: recentThreads } = useRecentAgentThreads(
		owner,
		rosterAgentIds,
		{
			enabled: !!owner && rosterAgentIds.length > 0,
			limit: RECENT_THREAD_LIMIT,
		},
	);
	const { data: mcpConversations = [] } = useClientActivityScopes({
		enabled: !!owner,
		limit: RECENT_THREAD_LIMIT,
		activityKind: "conversation",
		excludeCommandClients: true,
	});
	const { data: connectedClients = [] } = useConnectedClients(null, {
		enabled: !!owner,
	});
	const connectedAppGroups = useMemo(
		() => groupClients(connectedClients).filter((group) => group.connected),
		[connectedClients],
	);

	// MCP activity is write-time materialized per host conversation. Keep every
	// fetched thread and recent MCP conversation so one busy source type cannot
	// hide the others.
	const recentItems = useMemo(() => {
		return [
			...recentThreads.map((thread) => ({
				kind: "conversation" as const,
				at: thread.updatedAt,
				thread,
			})),
			...mcpConversations.map((conversation) => ({
				kind: "mcp" as const,
				at: conversation.lastCallAt,
				conversation,
			})),
		].sort((a, b) => b.at - a.at);
	}, [mcpConversations, recentThreads]);

	// "New agent" links straight to the builder chat with a prompt (see helpers
	// — the /$owner redirect would drop search params).
	const newAgent = newAgentLink({ owner, systemAgentId });
	// Collapsed icon-rail — only on the wide fixed sidebar (never embedded in the
	// narrow drawer, which is already a compact off-canvas panel).
	const isRail = collapsed && !embedded;

	if (isRail) {
		return (
			<aside className="fixed inset-y-0 left-0 z-40 flex w-14 flex-col items-center border-r border-border bg-sidebar-background text-sidebar-foreground">
				<div className="flex h-14 w-full items-center justify-center border-b border-sidebar-border">
					<button
						type="button"
						onClick={onToggleCollapsed}
						aria-label="Expand sidebar"
						title="Expand sidebar"
						className="flex h-9 w-9 items-center justify-center rounded-md text-sidebar-foreground/70 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
					>
						<PanelLeftOpen className="h-[18px] w-[18px]" />
					</button>
				</div>
				{owner ? (
					<div className="flex flex-1 flex-col gap-1 overflow-y-auto py-2">
						<RailButton
							label="Search"
							icon={Search}
							onClick={openCommandPalette}
						/>
						{(Object.keys(OWNER_SECTIONS) as OwnerSectionKey[]).map((key) => {
							const section = OWNER_SECTIONS[key];
							return (
								<RailButton
									key={key}
									label={section.label}
									active={isOwnerSectionActive(key, owner, pathname)}
									icon={section.icon}
									to={section.to}
									params={{ owner }}
									search={section.search}
								/>
							);
						})}
					</div>
				) : (
					<div className="flex-1" />
				)}
			</aside>
		);
	}

	return (
		<aside
			className={cn(
				"flex flex-col border-r border-border bg-sidebar-background text-sidebar-foreground",
				embedded ? "h-full w-full" : "fixed inset-y-0 left-0 z-40 w-[17.25rem]",
			)}
		>
			<div className="flex h-14 items-center gap-1 border-b border-sidebar-border px-2">
				<div className="min-w-0 flex-1">
					<OrganizationDropdown />
				</div>
				<button
					type="button"
					onClick={openCommandPalette}
					aria-label="Search"
					title="Search (⌘K)"
					className="flex h-8 w-8 shrink-0 items-center justify-center rounded-md text-sidebar-foreground/60 transition-colors hover:bg-sidebar-accent/60…132 tokens truncated…n>
				) : null}
			</div>

			{owner ? (
				<>
					<div className="flex flex-1 flex-col overflow-y-auto py-2">
						{/* Site map: Activity (events), Connect, Memory (entities).
						    Then the agent roster — agent row = chat. */}
						{(Object.keys(OWNER_SECTIONS) as OwnerSectionKey[]).map((key) => {
							const section = OWNER_SECTIONS[key];
							const active = isOwnerSectionActive(key, owner, pathname);
							// Context carries the workspace's entity types as children,
							// so it is a collapsible group rather than a plain row.
							if (key === "context") {
								return (
									<ContextGroup
										key={key}
										ownerSlug={owner}
										active={active}
										searchRecord={searchRecord}
									/>
								);
							}
							return (
								<NavRow
									key={key}
									to={section.to}
									params={{ owner }}
									search={section.search}
									active={active}
									icon={section.icon}
									label={section.label}
								/>
							);
						})}

						<SectionHeader
							label="Agents"
							icon={<LobuMark className="h-3 w-3 text-sidebar-foreground/40" />}
							action={
								newAgent ? (
									<Link
										to={newAgent.to as "/"}
										params={newAgent.params as never}
										search={newAgent.search as never}
										aria-label="New agent"
										title="New agent"
										className="flex h-5 w-5 items-center justify-center rounded-md text-sidebar-foreground/50 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
									>
										<Plus className="h-3.5 w-3.5" />
									</Link>
								) : null
							}
						/>
						{isLoading ? (
							<SidebarRowsSkeleton />
						) : (
							rosterAgents.map((agent) => (
								<AgentRow
									key={agent.agentId}
									ownerSlug={owner}
									agentId={agent.agentId}
									name={agent.name}
									status={agent.status}
									selected={agentId === agent.agentId}
								/>
							))
						)}
						{connectedAppGroups.map((group) => (
							<NavRow
								key={`client:${group.key}`}
								to="/$owner/connectors/client/$clientId"
								params={{ owner, clientId: group.clientId }}
								search={{ activity: undefined, view: undefined }}
								active={group.clientIds.includes(clientId ?? "")}
								leading={<ClientAppIcon name={group.title} />}
								label={group.title}
								trailing={
									<span
										aria-hidden="true"
										className="h-1.5 w-1.5 shrink-0 rounded-full bg-emerald-500"
									/>
								}
							/>
						))}

						{recentItems.length > 0 ? (
							<>
								<SectionHeader label="Recent" />
								{recentItems.map((item) => {
									if (item.kind === "mcp") {
										const title = item.conversation.title?.trim();
										const lastAction = item.conversation.lastAction?.trim();
										const clientName = item.conversation.clientName?.trim();
										const label =
											title ||
											(clientName
												? `${clientName} conversation`
												: "MCP conversation");
										return (
											<NavRow
												key={`mcp:${item.conversation.clientId}:${item.conversation.activityId}`}
												to="/$owner/connectors/client/$clientId"
												params={{ owner, clientId: item.conversation.clientId }}
												search={{
													activity: item.conversation.activityId,
													view: undefined,
												}}
												active={false}
												leading={
													<ClientAppIcon name={item.conversation.clientName} />
												}
												label={label}
												detail={
													title && lastAction !== title ? lastAction : undefined
												}
												lastActivityAt={item.at}
											/>
										);
									}

									const conv = item.thread;
									const label = conv.title;
									const isWeb = (conv.platform ?? "web") === "web";
									if (conv.platform === "behavior" && conv.behaviorId != null) {
										return (
											<NavRow
												key={`behavior:${conv.agentId}:${conv.behaviorId}`}
												to="/$owner/agents/$agentId/behaviors/$behaviorId"
												params={{
													owner,
													agentId: conv.agentId,
													behaviorId: String(conv.behaviorId),
												}}
												active={
													agentId === conv.agentId &&
													behaviorId === String(conv.behaviorId)
												}
												leading={<ListChecks className="h-3.5 w-3.5" />}
												label={label}
												detail="Behavior"
												lastActivityAt={conv.updatedAt}
											/>
										);
									}
									if (!isWeb) {
										return (
											<NavRow
												key={`conversation:${conv.agentId}:${conv.id}`}
												to="/$owner/agents/$agentId/conversations/$conversationId"
												params={{
													owner,
													agentId: conv.agentId,
													conversationId: conv.conversationId ?? conv.id,
												}}
												active={
													agentId === conv.agentId &&
													conversationId === (conv.conversationId ?? conv.id)
												}
												icon={platformIcon(conv.platform)}
												label={label}
												detail={
													conv.locationLabel ||
													(conv.platform
														? `${conv.platform.charAt(0).toUpperCase()}${conv.platform.slice(1)}`
														: undefined)
												}
												lastActivityAt={conv.updatedAt}
											/>
										);
									}

									const threadLink = agentThreadLink(
										owner,
										conv.agentId,
										conv.id,
									);
									return (
										<NavRow
											key={`chat:${conv.agentId}:${conv.id}`}
											to={threadLink.to}
											params={threadLink.params}
											active={agentId === conv.agentId && threadId === conv.id}
											icon={MessageSquare}
											label={label}
											detail="Chat"
											lastActivityAt={conv.updatedAt}
										/>
									);
								})}
							</>
						) : null}
					</div>

					<UserMenu />
				</>
			) : (
				<div className="flex flex-1 flex-col items-center justify-center px-4 text-center text-xs text-sidebar-foreground/50">
					Pick an organization to continue.
				</div>
			)}
		</aside>
	);
}
