import {
	Link,
	useLocation,
	useNavigate,
	useParams,
} from "@tanstack/react-router";
import {
	ChevronDown,
	ChevronRight,
	CircleUser,
	ListChecks,
	LogOut,
	MessageCircle,
	MessageSquare,
	PanelLeftClose,
	PanelLeftOpen,
	Plus,
	Search,
	Send,
	Settings2,
	Slack,
} from "lucide-react";
import { type ComponentType, type ReactNode, useMemo, useState } from "react";
import { ClientAppIcon } from "@/components/agents/app-icons";
import { LobuMark } from "@/components/brand/lobu-mark";
import { newAgentLink } from "@/components/sidebar/app-sidebar.helpers";
import { SidebarRowsSkeleton } from "@/components/sidebar/sidebar-skeleton";
import {
	Collapsible,
	CollapsibleContent,
	CollapsibleTrigger,
} from "@/components/ui/collapsible";
import {
	DropdownMenu,
	DropdownMenuContent,
	DropdownMenuItem,
	DropdownMenuSeparator,
	DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { EntityIcon } from "@/components/ui/entity-icon";
import { useOrgContext } from "@/hooks/use-org-context";
import { useWorkingAgents } from "@/hooks/use-working-agents";
import { agentChatLink, agentThreadLink } from "@/lib/agent-chat-routes";
import { useRecentAgentThreads } from "@/lib/api/agents";
import { useClientActivityScopes } from "@/lib/api/client-activity-scopes";
import { useEntityTypes } from "@/lib/api/entities";
import { signOut } from "@/lib/auth";
import { useAuthState } from "@/lib/auth-state";
import { formatTimeAgo } from "@/lib/format-utils";
import { memoryBrowseTypeSearch } from "@/lib/memory-browse";
import {
	isOwnerSectionActive,
	OWNER_SECTIONS,
	type OwnerSectionKey,
} from "@/lib/owner-sections";
import { cn } from "@/lib/utils";
import { OrganizationDropdown } from "./organization-dropdown";

type IconComponent = ComponentType<{ className?: string }>;

function openCommandPalette() {
	document.dispatchEvent(
		new KeyboardEvent("keydown", { key: "k", metaKey: true, bubbles: true }),
	);
}
	onToggleCollapsed?: () => void;
}) {
	const {
		agentId = null,
		threadId = null,
		conversationId = null,
		behaviorId = null,
	} = useParams({
		strict: false,
	}) as {
		agentId?: string;
		threadId?: string;
		conversationId?: string;
		behaviorId?: string;
	};
	const { pathname, search } = useLocation();
	const searchRecord = (search ?? {}) as Record<string, unknown>;
	const { currentOwner } = useOrgContext();
	const owner =
		currentOwner && !currentOwner.startsWith("@") ? currentOwner : null;
	// The Builder (system agent) is shown FIRST in the Agents roster (via
	// rosterAgents). Click an agent → chat; expand for configuration destinations.
	const { rosterAgents, systemAgentId, isLoading } = useWorkingAgents();
	const rosterAgentIds = useMemo(
		() => rosterAgents.map((agent) => agent.agentId),
		[rosterAgents],
	);
	const { threads: recentThreads } = useRecentAgentThreads(
		owner,
		rosterAgentIds,
		{
			enabled: !!owner && rosterAgentIds.length > 0,
			limit: RECENT_THREAD_LIMIT,
		},
	);
	const { data: mcpConversations = [] } = useClientActivityScopes({
		enabled: !!owner,
		limit: RECENT_THREAD_LIMIT,
		activityKind: "conversation",
		excludeCommandClients: true,
	});
	// MCP activity is write-time materialized per host conversation. Keep every
	// fetched thread and recent MCP conversation so one busy source type cannot
	// hide the others.
	const recentItems = useMemo(() => {
		return [
			...recentThreads.map((thread) => ({
				kind: "conversation" as const,
				at: thread.updatedAt,
				thread,
			})),
			...mcpConversations.map((conversation) => ({
				kind: "mcp" as const,
				at: conversation.lastCallAt,
				conversation,
			})),
		].sort((a, b) => b.at - a.at);
	}, [mcpConversations, recentThreads]);

	// "New agent" links straight to the builder chat with a prompt (see helpers
	// — the /$owner redirect would drop search params).
	const newAgent = newAgentLink({ owner, systemAgentId });
	// Collapsed icon-rail — only on the wide fixed sidebar (never embedded in the
	// narrow drawer, which is already a compact off-canvas panel).
	const isRail = collapsed && !embedded;

	if (isRail) {
		return (
			<aside className="fixed inset-y-0 left-0 z-40 flex w-14 flex-col items-center border-r border-border bg-sidebar-background text-sidebar-foreground">
				<div className="flex h-14 w-full items-center justify-center border-b border-sidebar-border">
					<button
						type="button"
						onClick={onToggleCollapsed}
						aria-label="Expand sidebar"
						title="Expand sidebar"
						className="flex h-9 w-9 items-center justify-center rounded-md text-sidebar-foreground/70 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
					>
						<PanelLeftOpen className="h-[18px] w-[18px]" />
					</button>
				</div>
				{owner ? (
					<div className="flex flex-1 flex-col gap-1 overflow-y-auto py-2">
						<RailButton
							label="Search"
							icon={Search}
