import { AGENT_CHAT_ROUTE } from "@/lib/agent-chat-routes";
import type { Organization } from "@/lib/api";

/** Prefill seeded into the builder composer when "New agent" is clicked. */
export const NEW_AGENT_PROMPT = "Create a new agent named ";

interface SidebarLink {
	to: string;
	params: Record<string, string>;
	search: Record<string, unknown>;
}

/**
 * Target for the sidebar "New agent" (+) action. Links STRAIGHT to the builder
 * chat — not `/$owner`, whose redirect to the builder drops search params — so
 * the create prompt survives. Returns null until the system agent id is known
 * (the action is hidden rather than dropping the prompt).
 *
 * Carries `new: true` alongside the prompt so each activation rotates the draft
 * (AgentChatPanel consumes+strips `?new`) — this both starts a fresh
 * conversation and, via the remount, re-applies the prompt every click, even
 * when already sitting on the builder chat with a stale `?prompt` in the URL.
 */
export function newAgentLink(params: {
	owner: string | null;
	systemAgentId: string | null;
}): SidebarLink | null {
	if (!params.owner || !params.systemAgentId) return null;
	return {
		to: AGENT_CHAT_ROUTE,
		params: { owner: params.owner, agentId: params.systemAgentId },
		search: { new: true, prompt: NEW_AGENT_PROMPT },
	};
}

interface SidebarSessionUser {
	name?: string | null;
	email?: string | null;
	image?: string | null;
}

interface SidebarActiveOrg {
	id?: string | null;
	slug?: string | null;
	name?: string | null;
	logo?: string | null;
}

interface SidebarOrgDisplayState {
	displayName: string;
	displayLogo?: string;
	displayInitial: string;
	activeSlug: string | null;
}

export function resolveOrganizationDisplay(params: {
	isAuthenticated: boolean;
	urlOrgSlug: string | null;
	activeOrg?: SidebarActiveOrg | null;
	sessionUser?: SidebarSessionUser | null;
	organizations: Organization[];
}): SidebarOrgDisplayState {
	const matchedUrlOrg = params.urlOrgSlug
		? params.organizations.find((org) => org.slug === params.urlOrgSlug)
		: null;

	if (params.isAuthenticated) {
		if (params.urlOrgSlug) {
			const displayName = matchedUrlOrg?.name || params.urlOrgSlug;
			return {
				displayName,
				displayLogo: matchedUrlOrg?.logo || undefined,
				displayInitial: displayName[0] || "W",
				activeSlug: params.urlOrgSlug,
			};
		}

		const displayName =
			params.activeOrg?.name || params.sessionUser?.name || "Personal";
		return {
			displayName,
			displayLogo:
				params.activeOrg?.logo || params.sessionUser?.image || undefined,
			displayInitial:
				params.activeOrg?.name?.[0] ||
				params.sessionUser?.name?.[0] ||
				params.sessionUser?.email?.[0] ||
				"P",
			activeSlug: params.activeOrg?.slug || null,
		};
	}

	// When the URL pins a workspace, the sidebar must reflect it — never fall
	// through to organizations[0], which can show a stale/cached org name on a
	// different URL (e.g. visitor's last-viewed workspace bleeding through).
	const publicOrg = params.urlOrgSlug ? matchedUrlOrg : params.organizations[0];
	const displayName =
		publicOrg?.name || params.urlOrgSlug || "Select Organization";
	return {
		displayName,
		displayLogo: publicOrg?.logo || undefined,
		displayInitial: displayName[0] || "W",
		activeSlug: params.urlOrgSlug || publicOrg?.slug || null,
	};
}

export function isOrganizationActive(params: {
	organization: Organization;
	urlOrgSlug: string | null;
	activeOrg?: SidebarActiveOrg | null;
}): boolean {
	if (params.urlOrgSlug) {
		return params.organization.slug === params.urlOrgSlug;
	}

	return (
		params.organization.id === params.activeOrg?.id ||
		params.organization.slug === params.activeOrg?.slug
	);
}
