import { createFileRoute, Outlet } from '@tanstack/react-router';

export const Route = createFileRoute('/$owner/agents')({
  component: () => <Outlet />,
});
import { Link, Outlet, useLocation, useNavigate } from "@tanstack/react-router";
import {
	Cpu,
	Inbox,
	ListChecks,
	Lock,
	Settings as SettingsIcon,
	Shield,
	Sparkles,
} from "lucide-react";
import { useEffect } from "react";
import {
	AgentEditorForm,
	type AgentSection,
} from "@/components/agents/agent-editor-form";
import { ProposalReviewShell } from "@/components/agents/proposal-review-shell";
import {
	WorkbenchHeader,
	type WorkbenchSection,
} from "@/components/agents/workbench-header";
import { useCurrentOrg } from "@/hooks/use-current-org";
import { useMembers } from "@/hooks/use-members";
import { useOrgContext } from "@/hooks/use-org-context";
import { agentChatLink } from "@/lib/agent-chat-routes";
import {
	type AgentItem,
	useAgents,
	useResolvedPath,
	useSystemAgentId,
} from "@/lib/api";
import { useAuthState } from "@/lib/auth-state";
import { cn } from "@/lib/utils";

/** Agent surfaces under the centered section dropdown. */
type AgentConfigDest =
	| "desk"
	| "behaviors"
	| "skills"
	| "guardrails"
	| "permissions"
	| "models"
	| "settings";

type AgentConfigMenuItem = WorkbenchSection<AgentConfigDest> & {
	/** Requires org settings admin (write-gate envelope). */
	adminOnly?: boolean;
};

const CONFIG_MENU: AgentConfigMenuItem[] = [
	{ key: "desk", label: "Desk", icon: Inbox },
	{ key: "behaviors", label: "Behaviors", icon: ListChecks },
	{ key: "skills", label: "Skills", icon: Sparkles },
	{ key: "guardrails", label: "Guardrails", icon: Shield },
	{ key: "permissions", label: "Permissions", icon: Lock, adminOnly: true },
	{ key: "models", label: "Models", icon: Cpu },
	{ key: "settings", label: "Settings", icon: SettingsIcon },
];

/** Menu rows visible for the current role. Exported for unit tests. */
export function filterConfigMenu(isAdmin: boolean) {
	return CONFIG_MENU.filter((item) => !item.adminOnly || isAdmin);
}

/** Active configure destination for the pathname, or null on chat/conversations. */
function activeConfigDest(
	base: string,
	pathname: string,
): AgentConfigDest | null {
	if (
		pathname === `${base}/chat` ||
		pathname.startsWith(`${base}/chat/`) ||
		pathname === `${base}/conversations` ||
		pathname.startsWith(`${base}/conversations/`)
	) {
		return "desk";
	}
	for (const { key } of CONFIG_MENU) {
		if (key === "desk") continue;
		if (
			pathname === `${base}/${key}` ||
			pathname.startsWith(`${base}/${key}/`)
		) {
			return key;
		}
	}
	// Legacy /identity URLs still resolve; identity fields live on Settings.
	if (pathname === `${base}/identity` || pathname === `${base}/identity/`) {
		return "settings";
	}
	return null;
}

function agentInitial(name: string): string {
	return name.trim().charAt(0).toUpperCase() || "?";
}

/** Centered agent name + section dropdown (Desk, Behaviors, Skills, …). */
function AgentWorkbenchHeader({
	owner,
	agentId,
	agentName,
	activeDest,
}: {
	owner: string;
	agentId: string;
	agentName: string;
	activeDest: AgentConfigDest | null;
}) {
	const navigate = useNavigate();
	const { orgContext } = useOrgContext();
	const { isAdmin } = useMembers(orgContext.organizationId);
	const chat = agentChatLink(owner, agentId);
	const items = filterConfigMenu(!!isAdmin);
	const activeSection = activeDest ?? "desk";
	const activeItem = CONFIG_MENU.find((item) => item.key === activeSection);

	return (
		<WorkbenchHeader
			identity={
				<Link
					to={chat.to}
					params={chat.params}
					className="flex min-w-0 items-center gap-2 rounded-md outline-none transition-colors hover:opacity-90 focus-visible:ring-2 focus-visible:ring-ring"
					title="Back to chat"
				>
					<span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-semibold text-foreground">
						{agentInitial(agentName)}
					</span>
					<h1 className="min-w-0 truncate text-base font-semibold tracking-tight">
						{agentName}
					</h1>
				</Link>
			}
			sections={items}
			activeSection={activeSection}
			activeItem={activeItem}
			sectionLabel="Agent section"
			highlightSection={activeDest !== null}
			onSectionSelect={(key) => {
				if (key === "desk") {
					void navigate({ to: chat.to, params: chat.params });
					return;
				}
				void navigate({
					to: `/$owner/agents/$agentId/${key}`,
					params: { owner, agentId },
				});
			}}
		/>
	);
}

export function AgentsWorkbenchLayout({
	owner,
	agentId,
}: {
	owner: string;
	agentId: string;
}) {
	const navigate = useNavigate();
	const { pathname } = useLocation();
	const { isAuthenticated } = useAuthState();
	const { isMember } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: canManageWorkspace,
	});
	useSystemAgentId({
		enabled: canManageWorkspace,
	});

	const selectedAgent = agents.find((a) => a.agentId === agentId) ?? null;
	const agentNotFound =
		!selectedAgent && !isAgentsLoading && canManageWorkspace;

	const base = `/${owner}/agents/${agentId}`;
	const chatPrefix = `${base}/chat`;
	const conversationsPrefix = `${base}/conversations`;
	const isAgentChat =
		pathname === chatPrefix || pathname.startsWith(`${chatPrefix}/`);
	// Inbound platform conversations (e.g. a Slack thread) live on their own
	// /conversations/$id route — treat them as chat for overflow layout.
	const isAgentConversation =
		pathname === conversationsPrefix ||
		pathname.startsWith(`${conversationsPrefix}/`);
	const isChat = isAgentChat || isAgentConversation;
	const activeDest = activeConfigDest(base, pathname);
	useEffect(() => {
		if (agentNotFound) {
			void navigate({ to: "/$owner", params: { owner }, replace: true });
		}
	}, [agentNotFound, navigate, owner]);

	const agentName = selectedAgent?.name ?? "Agent";

	return (
		<div className="flex min-h-0 flex-1 flex-col gap-3 overflow-hidden py-4 md:py-6">
			{/* Sidebar is the agent picker (→ Desk). Agent destinations live
			    in the centered header dropdown so the roster stays flat. */}
			<AgentWorkbenchHeader
				owner={owner}
				agentId={agentId}
				agentName={agentName}
				activeDest={activeDest}
			/>
			<div
				className={cn(
					"flex min-h-0 min-w-0 flex-1 flex-col px-4 lg:px-6",
					isChat ? "overflow-hidden" : "overflow-y-auto",
				)}
			>
				<Outlet />
			</div>
		</div>
	);
}

export function AgentConfigPane({
	agent,
	tab,
	runId,
}: {
	agent: AgentItem;
	tab: AgentSection;
	/** Slack config-approval deep link `?run_id`; when set, the ProposalReviewShell
	 *  fetches the held builder proposal and the form prefills it for review. */
	runId?: number;
}) {
	return (
		<div className="mx-auto w-full max-w-3xl pb-6">
			<ProposalReviewShell
				resource={{ kind: "agent", agentId: agent.agentId }}
				runId={runId}
			>
				{({ reviewMode, proposal, controlsDisabled }) => (
					<AgentEditorForm
						key={agent.agentId}
						mode={{ kind: "edit", agent }}
						section={tab}
						reviewMode={reviewMode}
						reviewProposal={proposal}
						reviewControlsDisabled={controlsDisabled}
					/>
				)}
			</ProposalReviewShell>
		</div>
	);
}

export function AgentConfigRoute({
	owner,
	agentId,
	tab,
	runId,
}: {
	owner: string;
	agentId: string;
	tab: AgentSection;
	runId?: number;
}) {
	const { orgContext, hasOrgContext } = useOrgContext();
	const { isLoading: isResolvedLoading } = useResolvedPath(
		`/${owner}`,
		orgContext,
	);
	const { isAuthenticated } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: canManageWorkspace,
	});
	const isLoading = canManageWorkspace
		? !hasOrgContext || isResolvedLoading || isAgentsLoading || isOrgLoading
		: isResolvedLoading || isOrgLoading;

	const selectedAgent = agents.find((a) => a.agentId === agentId) ?? null;

	if (isLoading || !selectedAgent) {
		return null;
	}

	return <AgentConfigPane agent={selectedAgent} tab={tab} runId={runId} />;
}
import { useCallback, useEffect, useState } from "react";
import { toast } from "sonner";
import { buildGeneratedAgentId } from "@/components/agents/agent-id-utils";
import {
	overlayFromProposal,
	type ReviewMode,
} from "@/components/agents/config-prefill";
import { ModelsListEditor } from "@/components/agents/models-list-editor";

import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { FormLoadingShell } from "@/components/ui/form-loading-shell";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
	Select,
	SelectContent,
	SelectItem,
	SelectTrigger,
	SelectValue,
} from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import {
	type AgentItem,
	type PendingProposal,
	useAgentConfig,
	useCreateAgent,
	useDeleteAgent,
	useSandboxes,
	useUpdateAgent,
	useUpdateAgentConfig,
} from "@/lib/api";

export type AgentEditorMode =
	| { kind: "create" }
	| { kind: "edit"; agent: AgentItem };

/** Which slice of the agent editor to render. Each maps to a tab on the agent
 *  detail page; the create flow ignores it (only the name/description show). */
export type AgentSection =
	| "settings"
	| "identity"
	| "skills"
	| "platforms"
	| "guardrails"
	| "models";

/**
 * The agent create/edit form. Rendered inline inside an agent-detail tab
 * (one `section` per tab) or on the create page. One `<form>` / one save
 * covers Identity + Guardrails (they round-trip together);
 * Providers, Skills, and Reach self-save on dedicated routes.
 */
export function AgentEditorForm({
	mode,
	section = "identity",
	existingAgentIds = [],
	onCreated,
	onCancel,
	onDone,
	reviewMode = "none",
	reviewProposal = null,
	reviewControlsDisabled = false,
}: {
	mode: AgentEditorMode;
	section?: AgentSection;
	existingAgentIds?: string[];
	onCreated?: (agentId: string) => void | Promise<void>;
	onCancel?: () => void;
	/** Called after a successful save/delete (and after create if no onCreated). */
	onDone?: () => void;
	/** Config-approval review state, supplied by the wrapping {@link ProposalReviewShell}
	 *  (Slack deep link `?run_id`). The shell owns the fetch + lifecycle + Approve/
	 *  Reject footer; this form only PREFILLS the proposed values (read-only) and
	 *  hides its own Save/Delete footer during an active review. Defaults ⇒ normal
	 *  edit (no review). */
	reviewMode?: ReviewMode;
	/** The held proposal to overlay when reviewMode is active; null otherwise. */
	reviewProposal?: PendingProposal | null;
	/** True when the shell says editable controls must be locked (fail-closed). */
	reviewControlsDisabled?: boolean;
}) {
	const isCreate = mode.kind === "create";
	const selectedAgent = mode.kind === "edit" ? mode.agent : null;
	const needsConfigEditorData =
		!isCreate &&
		section !== "platforms" &&
		section !== "skills" &&
		!!selectedAgent;
	const createAgent = useCreateAgent();
	const updateAgent = useUpdateAgent(selectedAgent?.agentId ?? "");
	const deleteAgent = useDeleteAgent(selectedAgent?.agentId ?? "");
	const updateAgentConfig = useUpdateAgentConfig(selectedAgent?.agentId ?? "");
	const { data: agentConfig, isLoading: isConfigLoading } = useAgentConfig(
		selectedAgent?.agentId,
		{ enabled: needsConfigEditorData },
	);

	// Review state is owned by the wrapping ProposalReviewShell and threaded in as
	// props; this form only consumes it to prefill + lock. `create` is never a
	// review (no agent to change), so ignore any review props then.
	const reviewActive = !isCreate && reviewMode === "active";
	const pendingProposal = reviewActive ? reviewProposal : null;

	// Callers remount this form (key on the agent id, or 'create') when the
	// target changes, so initial state can come straight from `mode` and the
	// async-loaded config below.
	const [name, setName] = useState(() =>
		mode.kind === "edit" ? mode.agent.name : "",
	);
	const [description, setDescription] = useState(() =>
		mode.kind === "edit" ? (mode.agent.description ?? "") : "",
	);
	const [identityMd, setIdentityMd] = useState("");
	const [soulMd, setSoulMd] = useState("");
	const [userMd, setUserMd] = useState("");
	const [models, setModels] = useState<string[]>([]);
	const [showToolCalls, setShowToolCalls] = useState(false);
	const [sandboxId, setSandboxId] = useState<string>("builtin");
