type IconComponent = ComponentType<{ className?: string }>;

function openCommandPalette() {
	document.dispatchEvent(
		new KeyboardEvent("keydown", { key: "k", metaKey: true, bubbles: true }),
	);
}

/** Bound the conversation fetch so the sidebar remains a compact recent list. */
const RECENT_THREAD_LIMIT = 12;

/** Icon for a conversation's source platform / system. */
function platformIcon(platform: string | undefined): IconComponent {
	switch (platform) {
		case "slack":
			return Slack;
		case "telegram":
			return Send;
		case "whatsapp":
		case "discord":
			return MessageCircle;
		default:
			return MessageSquare;
	}
}

function SectionHeader({
	label,
	icon,
	action,
}: {
	label: string;
	/** Optional leading glyph (e.g. the Lobu mark before "Agents"). */
	icon?: ReactNode;
	/** Optional trailing action; revealed on hover of the header row. */
	action?: ReactNode;
}) {
	return (
		<div className="group/section flex items-center justify-between px-3 pb-1 pt-3">
			<span className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wider text-sidebar-foreground/40">
				{icon}
				{label}
			</span>
			{action ? (
				<span className="opacity-0 transition-opacity group-hover/section:opacity-100 focus-within:opacity-100">
					{action}
				</span>
			) : null}
		</div>
	);
}

function NavRow({
	to,
	params,
	search,
	active,
	icon: Icon,
	leading,
	label,
	detail,
	trailing,
	);
	if (to) {
		return (
			<Link
				to={to as "/"}
				params={params as never}
				search={search as never}
				aria-label={label}
				title={label}
				className={className}
			>
				<Icon className="h-[18px] w-[18px]" />
			</Link>
		);
	}
	return (
		<button
			type="button"
			onClick={onClick}
			aria-label={label}
			title={label}
			className={className}
		>
			<Icon className="h-[18px] w-[18px]" />
		</button>
	);
}

export function AppSidebar({
	embedded = false,
	collapsed = false,
	onToggleCollapsed,
}: {
	embedded?: boolean;
	collapsed?: boolean;
	onToggleCollapsed?: () => void;
}) {
	const {
		agentId = null,
		threadId = null,
		conversationId = null,
		behaviorId = null,
	} = useParams({
		strict: false,
	}) as {
		agentId?: string;
		threadId?: string;
		conversationId?: string;
		behaviorId?: string;
	};
	const { pathname, search } = useLocation();
	const searchRecord = (search ?? {}) as Record<string, unknown>;
	const { currentOwner } = useOrgContext();
	const owner =
		currentOwner && !currentOwner.startsWith("@") ? currentOwner : null;
	// The Builder (system agent) is shown FIRST in the Agents roster (via
	// rosterAgents). Click an agent → chat; expand for configuration destinations.
	const { rosterAgents, systemAgentId, isLoading } = useWorkingAgents();
	const rosterAgentIds = useMemo(
		() => rosterAgents.map((agent) => agent.agentId),
		[rosterAgents],
	);
	const { threads: recentThreads } = useRecentAgentThreads(
		owner,
		rosterAgentIds,
		{
			enabled: !!owner && rosterAgentIds.length > 0,
			limit: RECENT_THREAD_LIMIT,
		},
	);
	const { data: mcpConversations = [] } = useClientActivityScopes({
		enabled: !!owner,
		limit: RECENT_THREAD_LIMIT,
		activityKind: "conversation",
		excludeCommandClients: true,
	});
	// MCP activity is write-time materialized per host conversation. Keep every
	// fetched thread and recent MCP conversation so one busy source type cannot
	// hide the others.
	const recentItems = useMemo(() => {
		return [
			...recentThreads.map((thread) => ({
				kind: "conversation" as const,
				at: thread.updatedAt,
				thread,
			})),
			...mcpConversations.map((conversation) => ({
				kind: "mcp" as const,
				at: conversation.lastCallAt,
				conversation,
			})),
		].sort((a, b) => b.at - a.at);
	}, [mcpConversations, recentThreads]);

	// "New agent" links straight to the builder chat with a prompt (see helpers
	// — the /$owner redirect would drop search params).
	const newAgent = newAgentLink({ owner, systemAgentId });
