						type="button"
						onClick={onToggleCollapsed}
						aria-label="Expand sidebar"
						title="Expand sidebar"
						className="flex h-9 w-9 items-center justify-center rounded-md text-sidebar-foreground/70 transition-colors hover:bg-sidebar-accent/60 hover:text-sidebar-foreground"
					>
						<PanelLeftOpen className="h-[18px] w-[18px]" />
					</button>
				</div>
				{owner ? (
					<div className="flex flex-1 flex-col gap-1 overflow-y-auto py-2">
						<RailButton
							label="Search"
							icon={Search}
							onClick={openCommandPalette}
						/>
						{(Object.keys(OWNER_SECTIONS) as OwnerSectionKey[]).map((key) => {
							const section = OWNER_SECTIONS[key];
							return (
								<RailButton
									key={key}
									label={section.label}
									active={isOwnerSectionActive(key, owner, pathname)}
									icon={section.icon}
									to={section.to}
		},
	);
	await throwIfNotOk(res, "Failed to start sign-in");
	return res.json() as Promise<AgentProviderOAuthStartResponse>;
}

/**
 * POST /inference-providers/oauth/complete — finish a provider sign-in.
 * Pass `{ code }` (authorization-code, `code#state`) OR
 * `{ deviceAuthId, userCode }` (device-code poll). Device polls return
 * `{ status: "pending" }` until the user authorizes.
 */
export async function completeProviderOAuth(
	orgSlug: string,
	providerId: string,
	input: { code: string } | { deviceAuthId: string; userCode: string },
): Promise<AgentProviderOAuthCompleteResponse> {
	const res = await fetchWithTimeout(
		agentsUrl(orgSlug, `/inference-providers/oauth/complete`),
		{
			method: "POST",
			headers: { "Content-Type": "application/json" },
			credentials: "include",
			body: JSON.stringify({ providerId, ...input }),
		},
	);
	await throwIfNotOk(res, "Failed to complete sign-in");
	return res.json() as Promise<AgentProviderOAuthCompleteResponse>;
}

