			return data.agents ?? [];
		},
		staleTime: 30_000,
	};
}

export function useAgents(options?: { enabled?: boolean }) {
	const { slug } = getPathScope();
	const opts = agentsQueryOptions(slug ?? "");
	return useQuery({
		...opts,
		enabled: !!slug && (options?.enabled ?? true),
	});
}

