import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { render } from "@testing-library/react";
import type { ReactNode } from "react";
import { describe, expect, it, vi } from "vitest";

// Both editors must derive their rows straight from the loaded agent config, so
// the FIRST committed render already reflects the saved skills/providers. The
// previous implementation mirrored the config into state via a `useEffect`,
// which left the first render empty until the effect ran — and the index reads
// that empty list as "no skills/providers yet" and flashes its add-a-thing
// empty state on every mount. These tests lock in the no-lag contract: when the
// config is loaded (isLoading === false), the rows are never empty for a
// configured agent.

const AGENT_CONFIG = {
	skillsConfig: {
		skills: [{ repo: "system/lobu", name: "lobu", enabled: true }],
	},
	installedProviders: [{ providerId: "gemini" }],
};

vi.mock("@/lib/api", async (importOriginal) => {
	const actual = await importOriginal<typeof import("@/lib/api")>();
	return {
		...actual,
		useAgentConfig: () => ({ data: AGENT_CONFIG, isLoading: false }),
		useAgentSkillsCatalog: () => ({ data: { catalog: [] }, isLoading: false }),
		useUpdateAgentConfig: () => ({ mutateAsync: vi.fn(), isPending: false }),
	};
});

vi.mock("@/lib/api/core", async (importOriginal) => {
	const actual = await importOriginal<typeof import("@/lib/api/core")>();
	return { ...actual, getPathScope: () => ({ slug: "test" }) };
});

import {
	AgentSkillEditorProvider,
	useAgentSkillEditor,
} from "@/components/agents/agent-skill-context";

function wrap(children: ReactNode) {
	const queryClient = new QueryClient({
		defaultOptions: { queries: { retry: false } },
	});
	return (
		<QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
	);
}

describe("agent editor hydration (no empty-state flash)", () => {
	it("skill editor exposes the config's skills on the first committed render", () => {
		const renders: Array<{ loaded: boolean; rows: number }> = [];
		function Probe() {
			const { skillRows, isLoading } = useAgentSkillEditor();
			renders.push({ loaded: !isLoading, rows: skillRows.length });
			return null;
		}
		render(
			wrap(
				<AgentSkillEditorProvider agentId="a1">
					<Probe />
				</AgentSkillEditorProvider>,
			),
		);

		// The very first render already has the skill — not an empty list that the
		// index would render as "add a skill".
		expect(renders[0]).toEqual({ loaded: true, rows: 1 });
		// And there is never a render where the editor is done loading but the rows
		// are still empty (the exact window the empty state used to slip through).
		expect(renders.some((r) => r.loaded && r.rows === 0)).toBe(false);
	});
});

