import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { toast } from 'sonner';
import {
  type ApiOrgContext,
  apiCall,
  fetchWithTimeout,
  apiErrorFor,
  getPathScope,
  normalizeOrgContext,
  resolveOrgSelector,
} from './core';

type NormalizedCtx = { organizationId: string | null; slug: string | null };
type OrgContextParam = ApiOrgContext | string | null | undefined;

/**
 * Each `createOrgQuery` / `createQuery` returns a `useXxx` hook that also
 * carries a `.queryOptions(...)` builder. Pass the same args you'd pass to the
 * hook; the builder returns a plain TanStack Query options object that route
 * loaders can hand to `queryClient.ensureQueryData(...)` for prefetching.
 *
 * This means the hook stays the only definition of (queryKey, queryFn,
 * staleTime) — the loader can't drift out of sync with the component.
 */
type QueryOptionsBuilder<TArgs extends readonly unknown[], TResult> = (
  ...args: TArgs
) => {
  queryKey: unknown[];
  queryFn: () => Promise<TResult>;
  staleTime?: number;
};

export type QueryHookWithOptions<TArgs extends readonly unknown[], TResult> = ((
  ...args: TArgs
) => ReturnType<typeof useQuery<TResult>>) & {
  queryOptions: QueryOptionsBuilder<TArgs, TResult>;
};

// ---------------------------------------------------------------------------
// Query factory for hooks that call apiCall with org-context resolution.
//
// The caller-facing argument tuple is TArgs (which includes the orgContext
// parameter at whatever position the original hook had it). The config
// receives the full TArgs tuple and is responsible for pulling out
// orgContext and building the body / queryKey.
// ---------------------------------------------------------------------------

export function createOrgQuery<TArgs extends readonly unknown[], TResult>(config: {
  queryKey: (ctx: NormalizedCtx, ...args: TArgs) => unknown[];
  tool: string;
  body: (...args: TArgs) => Record<string, unknown>;
  orgContext: (...args: TArgs) => OrgContextParam;
  transform?: (data: any) => TResult;
  enabled?: (ctx: NormalizedCtx, ...args: TArgs) => boolean;
  placeholderData?: (ctx: NormalizedCtx, ...args: TArgs) => TResult | undefined;
  staleTime?: number;
}): QueryHookWithOptions<TArgs, TResult> {
  const buildBaseOptions = (...args: TArgs) => {
    const ctx = normalizeOrgContext(config.orgContext(...args));
    return {
      ctx,
      queryKey: config.queryKey(ctx, ...args),
      queryFn: async (): Promise<TResult> => {
        const result = await apiCall<any>(
          config.tool,
          config.body(...args),
          resolveOrgSelector(ctx)
        );
        return config.transform ? config.transform(result) : (result as TResult);
      },
      staleTime: config.staleTime,
    };
  };

  const hook = (...args: TArgs) => {
    const base = buildBaseOptions(...args);
    const hasContext = !!(base.ctx.organizationId || base.ctx.slug);
    return useQuery({
      queryKey: base.queryKey,
      queryFn: base.queryFn,
      enabled: config.enabled?.(base.ctx, ...args) ?? hasContext,
      placeholderData: config.placeholderData?.(base.ctx, ...args) as never,
      staleTime: base.staleTime,
    });
  };

  (hook as QueryHookWithOptions<TArgs, TResult>).queryOptions = (...args: TArgs) => {
    const base = buildBaseOptions(...args);
    return { queryKey: base.queryKey, queryFn: base.queryFn, staleTime: base.staleTime };
  };

  return hook as QueryHookWithOptions<TArgs, TResult>;
}

// ---------------------------------------------------------------------------
// Query factory for hooks that call apiCall WITHOUT org-context
// ---------------------------------------------------------------------------

export function createQuery<TArgs extends readonly unknown[], TResult>(config: {
  queryKey: (...args: TArgs) => unknown[];
  tool: string;
  body: (...args: TArgs) => Record<string, unknown>;
  transform?: (data: any) => TResult;
  enabled?: (...args: TArgs) => boolean;
  staleTime?: number;
}): QueryHookWithOptions<TArgs, TResult> {
  const buildBaseOptions = (...args: TArgs) => ({
    queryKey: config.queryKey(...args),
    queryFn: async (): Promise<TResult> => {
      const result = await apiCall<any>(config.tool, config.body(...args));
      return config.transform ? config.transform(result) : (result as TResult);
    },
    staleTime: config.staleTime,
  });

  const hook = (...args: TArgs) => {
    const base = buildBaseOptions(...args);
    return useQuery({
      queryKey: base.queryKey,
      queryFn: base.queryFn,
      enabled: config.enabled?.(...args) ?? true,
      staleTime: base.staleTime,
    });
  };

  (hook as QueryHookWithOptions<TArgs, TResult>).queryOptions = buildBaseOptions;

  return hook as QueryHookWithOptions<TArgs, TResult>;
}

// ---------------------------------------------------------------------------
// Mutation factory
// ---------------------------------------------------------------------------

export function createMutation<TParams, TResult = unknown>(config: {
  tool: string;
  body: (params: TParams) => Record<string, unknown>;
  invalidateKeys: string[];
  transform?: (data: any) => TResult;
  checkError?: boolean; // default true -- throw if result.error exists
  // Static text, or a function of the mutation result for outcome-dependent
  // toasts (return null to suppress -- e.g. a create that queued an approval
  // instead of creating).
  successMessage?: string | ((result: TResult) => string | null);
  // Fallback toast text when a thrown error has no message. Defaults to the
  // generic 'Something went wrong'.
  errorMessage?: string;
  // Also invalidate on ERROR, not just success. Set for actions whose failure
  // usually means the UI is stale (e.g. approving a run another tab/replica
  // already resolved — "Run not found or not pending"): refetching then removes
  // the stale control that produced the error instead of leaving it clickable.
  invalidateOnError?: boolean;
}) {
  return () => {
    const queryClient = useQueryClient();
    const invalidateAll = () => {
      for (const key of config.invalidateKeys) {
        queryClient.invalidateQueries({ queryKey: [key] });
      }
    };
    return useMutation({
      mutationFn: async (params: TParams) => {
        const result = await apiCall<any>(config.tool, config.body(params));
        if (config.checkError !== false && result.error) {
          throw new Error(result.error);
        }
        return config.transform ? config.transform(result) : (result as TResult);
      },
