// ---------------------------------------------------------------------------
// REST mutation factory — for hooks that hit REST verbs (POST/PATCH/DELETE) on
// path-scoped endpoints via fetchWithTimeout + throwIfNotOk, rather than the
// tool-style `apiCall`. The returned hook takes the same hook-level args the
// original did (e.g. an agentId); `url` and `invalidate` receive the resolved
// slug plus those args. `body` is omitted for no-body verbs (DELETE). `read`
// controls response parsing: 'json' (default), 'none' (void), or a custom
// reader for non-standard envelopes.
// ---------------------------------------------------------------------------

export function createRestMutation<
  THookArgs extends readonly unknown[],
  TParams = void,
  TResult = unknown,
>(config: {
  method: 'POST' | 'PATCH' | 'PUT' | 'DELETE';
  // `url` gets the resolved slug, the mutate params (some endpoints put an id
  // from params in the path), and the hook-level args (e.g. agentId). `invalidate`
  // gets slug + args. Object form so call sites destructure only what they use.
  url: (ctx: { slug: string; params: TParams; args: THookArgs }) => string;
  body?: (params: TParams) => unknown;
  read?: 'json' | 'none' | ((res: Response) => Promise<TResult>);
  invalidate: (ctx: { slug: string | null; args: THookArgs }) => unknown[][];
  successMessage?: string;
  errorMessage: string;
}) {
  return (...hookArgs: THookArgs) => {
    const { slug } = getPathScope();
    const queryClient = useQueryClient();
    return useMutation({
      mutationFn: async (params: TParams): Promise<TResult> => {
        const init: RequestInit = { method: config.method, credentials: 'include' };
        if (config.body) {
          init.headers = { 'Content-Type': 'application/json' };
          init.body = JSON.stringify(config.body(params));
        }
        const res = await fetchWithTimeout(
          config.url({ slug: slug as string, params, args: hookArgs }),
          init
        );
        if (!res.ok) {
          throw await apiErrorFor(res);
        }
        const read = config.read ?? 'json';
        if (read === 'none') return undefined as TResult;
        if (read === 'json') return (await res.json()) as TResult;
        return read(res);
      },
      onSuccess: () => {
        for (const key of config.invalidate({ slug, args: hookArgs })) {
          queryClient.invalidateQueries({ queryKey: key });
        }
        if (config.successMessage) {
          toast.success(config.successMessage);
        }
      },
      onError: (error: Error) => {
        toast.error(error.message || config.errorMessage);
      },
    });
  };
}
