import { useAgents, useSystemAgentId } from "@/lib/api";

export function useWorkingAgents(enabled = true) {
	const { data: agents = [], ...rest } = useAgents({ enabled });
	const { data: systemAgent } = useSystemAgentId({ enabled });
	const systemAgentId = systemAgent?.systemAgentId ?? null;

	/** Non-system teammates — pickers and “working agents” that exclude Builder. */
	const workingAgents = useMemo(
		() =>
			systemAgentId
				? agents.filter((a) => a.agentId !== systemAgentId)
				: agents,
		[agents, systemAgentId],
	);

	const builderAgent = useMemo(
		() =>
			systemAgentId
				? (agents.find((a) => a.agentId === systemAgentId) ?? null)
				: null,
		[agents, systemAgentId],
	);

	/** Sidebar roster: Builder pinned first, then teammates (no duplicates). */
	const rosterAgents = useMemo(
		() => (builderAgent ? [builderAgent, ...workingAgents] : workingAgents),
		[builderAgent, workingAgents],
	);

	return {
		agents,
		workingAgents,
		rosterAgents,
		builderAgent,
		systemAgentId,
		...rest,
	};
}
