// ============================================================
// Mutation hooks
// ============================================================

export const useCreateAgent = createRestMutation<
	[],
	{ agentId: string; name: string; description?: string },
	AgentDetail
>({
	method: "POST",
	url: ({ slug }) => agentsUrl(slug),
	body: (params) => params,
	invalidate: () => [["agents"]],
	successMessage: "Agent created",
	errorMessage: "Failed to create agent",
});

export const useUpdateAgent = createRestMutation<
	[agentId: string],
	{ name?: string; description?: string },
	AgentDetail
>({
	method: "PATCH",
	url: ({ slug, args: [agentId] }) => agentsUrl(slug, `/${agentId}`),
	body: (params) => params,
	invalidate: ({ slug, args: [agentId] }) => [
		["agents"],
		["agent", slug, agentId],
	],
	errorMessage: "Failed to update agent",
});

export const useDeleteAgent = createRestMutation<[agentId: string]>({
	method: "DELETE",
	url: ({ slug, args: [agentId] }) => agentsUrl(slug, `/${agentId}`),
	read: "none",
	invalidate: () => [["agents"]],
	successMessage: "Agent deleted",
	errorMessage: "Failed to delete agent",
});

export const useUpdateAgentConfig = createRestMutation<
	[agentId: string],
	Partial<AgentSettings>,
	AgentSettings
>({
	method: "PATCH",
	url: ({ slug, args: [agentId] }) => agentsUrl(slug, `/${agentId}/config`),
	body: (params) => params,
	invalidate: ({ slug, args: [agentId] }) => [
		["agent-config", slug, agentId],
		["agent", slug, agentId],
	],
	errorMessage: "Failed to update agent config",
});

