import type {
  ConnectionConnectorGroup,
  ConnectionFacets,
  ConnectorDefinitionItem,
} from "@/lib/api/connections";

/**
 * Connector capability facets + the shared filter vocabulary used by BOTH the
 * connectors grid (`/connectors`) and the Add-connector catalog picker. Keeping
 * the filter keys, labels, and matcher here means the two chip rows can never
 * drift — add a filter once and both pages get it.
 */

/** The capability facets a connector card advertises. */
export type ConnectorFacet =
  | "data"
  | "chat"
  | "actions"
  | "device"
  | "inference"
  | "runtime";

/**
 * Every filter chip a connector list can offer.
 *
 * Capability only. The auth method a connector uses (OAuth / API key / app
 * install) was three more chips, and none of them answered a question anyone
 * brings to this page: you look for what a connector can DO, and how it
 * authenticates is a detail of setting up the one you already picked. Worse,
 * they overlapped the capability chips almost exactly — nearly every OAuth
 * connector is also a Data connector — so they read as a second, redundant
 * spelling of the row above.
 */
export type ConnectorFilter =
  | "all"
  | "data"
  | "chat"
  | "actions"
  | "inference"
  | "runtime"
  | "device";

/** The canonical chip label for every filter. */
export const CONNECTOR_FILTER_LABELS: Record<ConnectorFilter, string> = {
  all: "All",
  data: "Data",
  chat: "Chat",
  actions: "Actions",
  inference: "Inference",
  runtime: "Runtime",
  device: "On device",
};

/**
 * A connector declares itself chat-capable via the `x-lobu-chat-platform`
 * marker in its `options_schema` (slack/telegram/discord/… all set it). This is
 * the DEFINITION-level signal — the same one the server reads at connect time —
 * so an uninstalled chat connector can advertise chat before any connection
 * exists. Catalog use only: per-connection `facets.chat` stays live-only (it
 * means "a live bot adapter", which the run-on-device picker keys off).
 */
function connectorDeclaresChat(
  connector: ConnectorDefinitionItem
): boolean {
  return connector.options_schema?.["x-lobu-chat-platform"] != null;
}

/** Whether a connector runs on a device (needs a local runtime to execute). */
export function connectorIsDeviceBound(
  connector: ConnectorDefinitionItem
): boolean {
  return !!connector.runtime || !!connector.required_capability;
}

/**
 * Derive a connector's capability facets. A live connection group's facets win
 * (they reflect actual configured state); otherwise fall back to what the
 * connector definition declares, so an uninstalled connector still advertises
 * what it CAN do (data/chat/actions).
 */
export function deriveConnectorFacets(
  connector: ConnectorDefinitionItem,
  group?: ConnectionConnectorGroup
): ConnectionFacets {
  const feeds = connector.feeds_schema
    ? Object.keys(connector.feeds_schema).length > 0
    : false;
  const actions =
    connector.has_operations ||
    (connector.actions_schema
      ? Object.keys(connector.actions_schema).length > 0
      : false);
  return {
    data: group?.facets.data ?? feeds,
    chat: group?.facets.chat ?? connectorDeclaresChat(connector),
    actions: group?.facets.actions ?? actions,
    audience: group?.facets.audience ?? false,
    // A connector definition never serves inference or runtime — model
    // providers and sandboxes live in their own tables and are synthesized into
    // the list as their own rows (see the connectors index). Nothing derived
    // from a connector can flip either.
    inference: false,
    runtime: false,
  };
}

/** The connector + derived state a filter is evaluated against. */
export interface ConnectorFilterItem {
  connector: ConnectorDefinitionItem;
  facets: ConnectionFacets;
  /** Installed-but-unconfigured. Optional — catalog entries have no setup state. */
  needsSetup?: boolean;
  /**
   * The row IS a device, rather than a connector bound to one. A device row
   * carries neither `runtime` nor `required_capability` — it is the thing
   * those fields point AT — so without this flag "On device" listed Screen
   * Time and Photos but not a single actual device.
