			<div className="mb-6">
				<h1 className="text-xl font-semibold tracking-tight">Agents</h1>
				<p className="mt-1 text-sm text-muted-foreground">
					Connect an external agent or build one that Lobu manages.
				</p>
			</div>

			{agents.length === 0 ? (
				<div className="flex flex-col items-center gap-4 rounded-lg border border-dashed px-6 py-12 text-center">
					<div className="flex h-10 w-10 items-center justify-center rounded-full bg-muted text-muted-foreground">
						<Bot className="h-5 w-5" />
					</div>
					<div>
						<h2 className="font-medium">Bring your first agent</h2>
						<p className="mt-1 max-w-md text-sm text-muted-foreground">
							Connect an agent you already use, or create a managed agent here.
						</p>
					</div>
					<div className="flex flex-wrap justify-center gap-2">
						<Button asChild>
							<Link
								to="/$owner/connectors"
								params={{ owner }}
								search={{ filter: "agents" }}
