								<CircleUser className="h-4 w-4" />
								Connect your agent
							</Link>
						</Button>
						<Button asChild variant="outline">
							<Link to="/$owner/agents/new" params={{ owner }}>
								<Plus className="h-4 w-4" />
								Build a managed agent
							</Link>
						</Button>
					</div>
				</div>
			) : (
