// `resolve_path` return an empty envelope (no entity) — the realistic shape for
// both a bare org root and a non-existent entity path.
async function mountAt(path: string, authenticated: boolean) {
	setAuthStateMock(authenticated ? "authenticated" : "anonymous");
	const queryClient = new QueryClient({
		defaultOptions: {
			queries: { retry: false, staleTime: Number.POSITIVE_INFINITY },
		},
	});
	const { routeTree } = await import("@/routeTree.gen");
	const router = createRouter({
		routeTree,
		history: createMemoryHistory({ initialEntries: [path] }),
		context: { queryClient },
		defaultPreload: false,
	});
	const result = render(
		<QueryClientProvider client={queryClient}>
			{/** biome-ignore lint/suspicious/noExplicitAny: memory router variant */}
			<RouterProvider router={router as any} />
		</QueryClientProvider>,
	);
	await new Promise((resolve) => setTimeout(resolve, 0));
	return { router, ...result };
}

describe("bare org root", () => {
	let errorSpy: ReturnType<typeof vi.spyOn>;
	beforeEach(() => {
		errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
	});
	afterEach(() => errorSpy.mockRestore());

	// The first mount in this file pays a one-time lazy-chunk compile cost under
	// jsdom (the home-chat route pulls the runtime-provider chunk) that can exceed
	// Vitest's 5s default on a cold / loaded runner — the same cold-start the
	// all-routes smoke absorbs with a generous timeout. Warm follow-up mounts run
	// in ~1.8s.
	it("shows zero-agent onboarding at the bare org root without resolving a system agent", async () => {
		let systemAgentRequests = 0;
		server.use(
			http.get("*/api/:slug/agents/system-agent", () => {
				systemAgentRequests += 1;
				return HttpResponse.json({ systemAgentId: "lobu-builder" });
			}),
		);
		const { router, findByRole, unmount } = await mountAt("/test-org", true);
		expect(router.state.location.pathname).toBe("/test-org");
		expect(
			await findByRole("link", { name: "Connect your agent" }),
		).toHaveAttribute("href", "/test-org/connectors?filter=agents");
		expect(
			await findByRole("link", { name: "Build a managed agent" }),
		).toHaveAttribute("href", "/test-org/agents/new");
		expect(systemAgentRequests).toBe(0);
		unmount();
	}, 20_000);

	it("renders Not Found for an entity path that resolves to no entity", async () => {
		const { findByText, unmount } = await mountAt(
			"/test-org/no/such/entity",
			true,
		);
		// The resolver no longer funnels missing entities to /connectors — a path
		// that points at nothing is a terminal Not Found.
		expect(await findByText("Not Found")).toBeTruthy();
		unmount();
	});

	it("does not resolve or provision a system agent on child routes", async () => {
		let systemAgentRequests = 0;
		server.use(
			http.get("*/api/:slug/agents/system-agent", () => {
				systemAgentRequests += 1;
				return HttpResponse.json({ systemAgentId: "lobu-builder" });
			}),
		);
		const { unmount } = await mountAt("/test-org/memory", true);
		await new Promise((resolve) => setTimeout(resolve, 0));
		expect(systemAgentRequests).toBe(0);
		unmount();
	});

	it("does not resolve /members/:userId as a member entity page", async () => {
		const { findByText, unmount } = await mountAt(
			"/test-org/members/u_42",
			true,
		);
		expect(await findByText("Not Found")).toBeTruthy();
		unmount();
	});

	it.each([
		"/test-org/devices",
		"/test-org/events",
		"/test-org/sources",
		"/test-org/connections",
		"/test-org/devices/connect",
	])("returns Not Found for removed owner route %s", async (path) => {
		const { findByText, unmount } = await mountAt(path, true);
		expect(await findByText("Not Found")).toBeTruthy();
		unmount();
	});

	it("renders the load error on the owner home when the query fails", async () => {
		server.use(
			http.get("*/api/:slug/agents/system-agent", () =>
				HttpResponse.json({ error: "unauthorized" }, { status: 401 }),
			),
		);
		// The hook reads the browser path rather than the memory router's history.
		const prev = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org");
		try {
			const { findByText, queryByText, unmount } = await mountAt(
				"/test-org",
				true,
			);
			expect(
				await findByText(/Couldn't load the workspace builder/i),
			).toBeTruthy();
			expect(await findByText(/unauthorized/i)).toBeTruthy();
			expect(queryByText(/not provisioned yet/i)).toBeNull();
			unmount();
		} finally {
			window.history.replaceState({}, "", prev);
		}
	}, 20_000);

	it("sends a signed-out visitor to sign-in instead of rendering the 401", async () => {
		server.use(
			http.post("*/api/:slug/resolve_path", () =>
				HttpResponse.json({ error: "unauthorized" }, { status: 401 }),
			),
			http.get("*/api/:slug/agents/system-agent", () =>
				HttpResponse.json({ error: "unauthorized" }, { status: 401 }),
			),
		);
		const prev = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org");
		try {
			const { router, queryByText, unmount } = await mountAt(
				"/test-org",
				false,
			);
			await waitFor(() =>
				expect(router.state.location.pathname).toBe("/auth/login"),
			);
			expect(router.state.location.search).toMatchObject({
				callbackUrl: "/test-org",
				intent: "sign-in",
			});
			expect(queryByText(/Couldn't load the workspace builder/i)).toBeNull();
			unmount();
		} finally {
			window.history.replaceState({}, "", prev);
		}
	}, 20_000);

	it("does not misread an outage as a reason to sign in", async () => {
		server.use(
			http.post("*/api/:slug/resolve_path", () =>
				HttpResponse.json({ error: "unavailable" }, { status: 503 }),
			),
			http.get("*/api/:slug/agents/system-agent", () =>
				HttpResponse.json({ error: "unavailable" }, { status: 503 }),
			),
		);
		const prev = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org");
		try {
			const { router, findByText, unmount } = await mountAt("/test-org", false);
			expect(
				await findByText(/Couldn't load the workspace builder/i),
			).toBeTruthy();
			expect(router.state.location.pathname).toBe("/test-org");
			unmount();
		} finally {
			window.history.replaceState({}, "", prev);
		}
	}, 20_000);

	it('still renders "not provisioned yet" on a 200 with a null id', async () => {
		server.use(
			http.get("*/api/:slug/agents/system-agent", () =>
				HttpResponse.json({ systemAgentId: null }),
			),
		);
		const prev = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org");
		try {
			const { findByText, queryByText, unmount } = await mountAt(
				"/test-org",
				true,
			);
			expect(await findByText(/not provisioned yet/i)).toBeTruthy();
			expect(queryByText(/Couldn't load the workspace builder/i)).toBeNull();
			unmount();
		} finally {
			window.history.replaceState({}, "", prev);
		}
	}, 20_000);
});

