import {
	createFileRoute,
	Link,
	Navigate,
	Outlet,
	useLocation,
} from "@tanstack/react-router";
import { Bot } from "lucide-react";
import { NotificationPeekProvider } from "@/components/peek/notification-peek-context";
import { NotificationPeekPane } from "@/components/peek/notification-peek-pane";
import { agentChatLink, isOwnerHomePath } from "@/lib/agent-chat-routes";
import { type AgentItem, useAgents, useWorkspaceRoot } from "@/lib/api";
import { isServerError } from "@/lib/api/core";
import { useAuthState } from "@/lib/auth-state";
import { useAnonymousSignInRedirect } from "@/lib/sign-in-redirect";

export const Route = createFileRoute("/$owner")({
	loader: ({ context: { queryClient }, params }) => {
		// Fire-and-forget — awaiting here blocks child routes behind the router's
		// generic pending UI instead of each page's shape-matched skeletons.
		void queryClient.prefetchQuery(
			useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
		);
		void queryClient.prefetchQuery(useAgents.queryOptions(params.owner));
	},
	// Home resolves its agent inventory before choosing Activity or the agent
	// roster; null avoids a wrong-shaped shell while the owner route loads.
	pendingComponent: () => null,
	component: OwnerLayoutRoute,
});

function OwnerLayoutRoute() {
	const { owner } = Route.useParams();
	const { pathname } = useLocation();
	const isHomeView = isOwnerHomePath(owner, pathname);
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: isHomeView,
	});

	// Auth gate for the whole owner subtree — the chokepoint every
	// `/{owner}/...` page passes through. On a per-org subdomain this is also
	// the landing route: `createSubdomainHistory` rewrites `/` to `/${owner}`
	// before matching, so the `/` route's sign-in redirect never runs there and
	// a signed-out visitor was shown the raw 401 body as a product error.
	// Reuses the workspace query this route's loader already prefetches.
	const {
		data: workspaceRoot,
		isLoading: isWorkspaceLoading,
		error: workspaceError,
	} = useWorkspaceRoot(owner, { slug: owner });
	const { session, isReady: authReady } = useAuthState();
	// A 5xx or transport failure is an outage, not an authz problem; bouncing
	// there would read as "you are not allowed here". Only a refusal — chiefly
	// the 401 a private org answers anonymously — should reach sign-in.
	const isWorkspaceUnavailable =
		isServerError(workspaceError) && !workspaceRoot?.workspace;
	const isRedirectingToSignIn = useAnonymousSignInRedirect({
		active:
			!isWorkspaceLoading &&
			!isWorkspaceUnavailable &&
			authReady &&
			!session &&
			!workspaceRoot?.workspace,
		owner,
	});

	// Render nothing while the sign-in navigation lands, so no page in this
	// subtree flashes an auth error on the way to the login screen.
	if (isRedirectingToSignIn) return null;

	if (!isHomeView) {
		return (
			<NotificationPeekProvider>
				<div className="flex min-h-0 flex-1 flex-row">
					{/* `overflow-y-auto`, not `overflow-hidden`: this wrapper is the
					    scroll container for every owner sub-page. The peek pane makes
					    it a flex row, so the shell's outer scroller is clamped to the
					    row height and never sees page overflow — clipping here instead
					    of scrolling made long pages unreachable below the fold. */}
					<div className="flex min-h-0 min-w-0 flex-1 flex-col overflow-y-auto">
						<Outlet />
					</div>
					<NotificationPeekPane />
				</div>
			</NotificationPeekProvider>
		);
	}

	if (isAgentsLoading) {
		return (
			<div className="mx-auto flex w-full max-w-2xl flex-1 flex-col gap-3 px-4 py-8 lg:px-6">
				<div className="h-7 w-28 animate-pulse bg-muted" />
				<div className="h-4 w-72 animate-pulse bg-muted" />
				<div className="mt-3 h-24 animate-pulse rounded-lg border bg-muted/30" />
			</div>
		);
	}

	if (agents.length === 0) {
		return (
			<Navigate to="/$owner/activity" params={{ owner }} search={{}} replace />
		);
	}

	return <WorkspaceAgentsHome owner={owner} agents={agents} />;
}

function WorkspaceAgentsHome({
	owner,
	agents,
}: {
	owner: string;
	agents: AgentItem[];
}) {
	return (
		<div className="mx-auto flex w-full max-w-2xl flex-1 flex-col px-4 py-8 lg:px-6">
			<div className="mb-6">
				<h1 className="text-xl font-semibold tracking-tight">Agents</h1>
				<p className="mt-1 text-sm text-muted-foreground">
					Connect an external agent or build one that Lobu manages.
				</p>
			</div>

			<div className="overflow-hidden rounded-lg border">
				{agents.map((agent, index) => {
					const link = agentChatLink(owner, agent.agentId);
					return (
						<Link
							key={agent.agentId}
							to={link.to}
							params={link.params}
							className={`flex items-center gap-3 px-3 py-3 transition-colors hover:bg-accent/50 ${
								index === agents.length - 1 ? "" : "border-b"
							}`}
						>
							<span className="flex h-8 w-8 items-center justify-center rounded-md border text-muted-foreground">
								<Bot className="h-4 w-4" />
							</span>
							<span className="min-w-0 flex-1">
								<span className="block truncate text-sm font-medium">
									{agent.name}
								</span>
								<span className="block truncate text-xs text-muted-foreground">
									{agent.description || "Agent"}
								</span>
							</span>
						</Link>
					);
				})}
			</div>
		</div>
	);
}
}

