   351	/**
   352	 * Convert a route file under `src/app/` to the canonical route id that
   353	 * TanStack would generate. Mirrors the file-router conventions so adding a
   354	 * new route file fails this test until a smoke entry covers it.
   355	 *
   356	 * Examples:
   357	 *   /index.tsx                       -> /
   358	 *   /auth/login.tsx                  -> /auth/login
   359	 *   /$owner/memory/index.tsx        -> /$owner/memory
   360	 *   /$owner/agents.tsx               (layout, ignored — has matching `agents/` dir)
   361	 */
   362	function fileToRouteId(
   363		relativePath: string,
   364		allFiles: string[],
   365	): string | null {
   366		// Strip leading `/` and `.tsx`
   367		const trimmed = relativePath.replace(/^\//, "").replace(/\.tsx$/, "");
   368		const segments = trimmed.split("/");
   369		const last = segments[segments.length - 1];
   370	
   371		// `index.tsx` collapses to its parent.
   372		if (last === "index") {
   373			segments.pop();
   374		} else {
   375			// A bare file `foo.tsx` whose sibling directory `foo/` exists is a layout
   376			// route — its concrete page lives in `foo/index.tsx`. Skip it so we don't
   377			// demand a smoke entry for the layout itself.
   378			const parent = segments.slice(0, -1).join("/");
   379			const directoryForm = parent ? `${parent}/${last}/` : `${last}/`;
   380			const hasSiblingDir = allFiles.some((f) =>
   381				f.replace(/^\//, "").startsWith(directoryForm),
   382			);
   383			if (hasSiblingDir) return null;
   384		}
   385	
   386		if (segments.length === 0) return "/";
   387		return `/${segments.join("/")}`;
   388	}
