/**
 * Search keys owned by the right-side peek pane. Target fields are namespaced
 * so opening and closing a preview cannot overwrite the current route's own
 * `view`, `run_ids`, `agent`, or `behavior` filters.
 */
export const PEEK_SEARCH_KEYS = [
	"peek",
	"peek_run_id",
	"peek_content_ids",
	"peek_agent",
	"peek_behavior",
	"peek_behavior_run_id",
	"peek_view",
] as const;

export type PeekSearchKey = (typeof PEEK_SEARCH_KEYS)[number];
export type PeekSearch = Partial<Record<PeekSearchKey, string>>;

function isPeekOpenFlag(value: unknown): boolean {
	return value === "1" || value === "true" || value === true || value === 1;
}

export function pickPeekSearch(
	search: Record<string, unknown> | undefined | null,
): PeekSearch {
	if (!search) return {};
	const out: PeekSearch = {};
	for (const key of PEEK_SEARCH_KEYS) {
		const value = search[key];
		if (value == null || value === "") continue;
		if (key === "peek") {
			if (isPeekOpenFlag(value)) out.peek = "1";
			continue;
		}
		if (typeof value === "string" && value.trim()) {
			out[key] = value.trim();
		} else if (typeof value === "number" && Number.isFinite(value)) {
			out[key] = String(value);
		}
	}
	return out;
}

export function omitPeekSearch<T extends Record<string, unknown>>(
	search: T,
): Omit<T, PeekSearchKey> {
	const next = { ...search };
	for (const key of PEEK_SEARCH_KEYS) delete next[key];
	return next as Omit<T, PeekSearchKey>;
}

export function hasPeekFlag(
	search: Record<string, unknown> | undefined,
): boolean {
	return isPeekOpenFlag(search?.peek);
}

/** Convert namespaced peek state into the destination href rendered by the pane. */
export function destinationHrefFromPeekSearch(
	owner: string,
	search: PeekSearch,
): string | null {
	if (search.peek_run_id && isIdList(search.peek_run_id)) {
		const query = new URLSearchParams({
			run_ids: search.peek_run_id,
		});
		return `/${owner}/activity?${query.toString()}`;
	}

	if (search.peek_content_ids && isIdList(search.peek_content_ids)) {
		const query = new URLSearchParams({
			content_ids: search.peek_content_ids,
		});
		return `/${owner}/activity?${query.toString()}`;
	}

	if (search.peek_agent && search.peek_behavior) {
		const query = new URLSearchParams();
		if (search.peek_view === "activity" || search.peek_view === "definition") {
			query.set("view", search.peek_view);
		}
		if (
			search.peek_behavior_run_id &&
			/^\d+$/.test(search.peek_behavior_run_id)
		) {
			query.set("run_id", search.peek_behavior_run_id);
		}
		const suffix = query.size > 0 ? `?${query.toString()}` : "";
		return `/${owner}/agents/${search.peek_agent}/behaviors/${search.peek_behavior}${suffix}`;
	}

	return null;
}

/** Convert a peekable destination href into namespaced current-route search. */
export function peekSearchFromDestinationHref(href: string): PeekSearch | null {
	const { pathname, search } = parseAppHref(href);
	const segments = pathname.split("/").filter(Boolean);

	if (
		segments.length === 2 &&
		(segments[1] === "activity" || segments[1] === "memory")
	) {
		const runIds = search?.run_ids;
		if (runIds && isIdList(runIds)) {
			return { peek: "1", peek_run_id: runIds };
		}
		const contentIds = search?.content_ids;
		if (contentIds && isIdList(contentIds)) {
			return { peek: "1", peek_content_ids: contentIds };
		}
		return null;
	}

	if (
		segments.length === 5 &&
		segments[1] === "agents" &&
		segments[3] === "behaviors"
	) {
		const out: PeekSearch = {
			peek: "1",
			peek_agent: segments[2],
			peek_behavior: segments[4],
		};
		if (search?.view === "activity" || search?.view === "definition") {
			out.peek_view = search.view;
		}
		if (search?.run_id && /^\d+$/.test(search.run_id)) {
			out.peek_behavior_run_id = search.run_id;
		}
		return out;
	}

	return null;
}

function isIdList(value: string): boolean {
	const ids = value.split(",");
	return (
		ids.length > 0 &&
		ids.length <= 50 &&
		ids.every((id) => /^\d+$/.test(id.trim()) && Number(id) > 0)
	);
}

export function mergePeekSearch(
	current: Record<string, unknown> | undefined,
	peek: PeekSearch,
): Record<string, unknown> {
	const base: Record<string, unknown> = { ...current };
	for (const key of PEEK_SEARCH_KEYS) delete base[key];
	for (const [key, value] of Object.entries(peek)) {
		if (value) base[key] = value;
	}
	return base;
}
