new file mode 100644
index 0000000000000000000000000000000000000000..789cddfe766c969e917a0c8745e37f5107b58a05
--- /dev/null
+++ b/src/app/$owner/agents/index.tsx
@@ -0,0 +1,55 @@
+import { useQueryClient } from "@tanstack/react-query";
+import { createFileRoute, useNavigate } from "@tanstack/react-router";
+import { AgentEditorForm } from "@/components/agents/agent-editor-form";
+import { useCurrentOrg } from "@/hooks/use-current-org";
+import { type AgentItem, useAgents } from "@/lib/api";
+import { useAuthState } from "@/lib/auth-state";
+
+export const Route = createFileRoute("/$owner/agents/")({
+	component: NewAgentPage,
+});
+
+function NewAgentPage() {
+	const { owner } = Route.useParams();
+	const navigate = useNavigate();
+	const queryClient = useQueryClient();
+	const { isAuthenticated } = useAuthState();
+	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
+	const canManageWorkspace = isAuthenticated && isMember;
+	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
+		enabled: canManageWorkspace,
+	});
+
+	if (isOrgLoading || !canManageWorkspace || isAgentsLoading) return null;
+
+	return (
+		<div className="mx-auto flex w-full max-w-2xl flex-1 flex-col px-4 py-8 lg:px-6">
+			<div className="mb-6">
+				<h1 className="text-xl font-semibold tracking-tight">
+					Build a managed agent
+				</h1>
+				<p className="mt-1 text-sm text-muted-foreground">
+					Create an agent that Lobu runs and manages for this workspace.
+				</p>
+			</div>
+			<AgentEditorForm
+				mode={{ kind: "create" }}
+				existingAgentIds={agents.map((agent) => agent.agentId)}
+				onCreated={async (agent) => {
+					const queryKey = ["agents", owner] as const;
+					await queryClient.refetchQueries({ queryKey });
+					queryClient.setQueryData<AgentItem[]>(queryKey, (current = []) =>
+						current.some((item) => item.agentId === agent.agentId)
+							? current
+							: [...current, agent],
+					);
+					await navigate({
+						to: "/$owner/agents/$agentId/settings",
+						params: { owner, agentId: agent.agentId },
+						search: { run_id: undefined },
+					});
+				}}
+			/>
+		</div>
+	);
+}
