/** A single message in a streaming (chat-channel) feed's transcript. */
export interface ChannelFeedMessage {
	timestamp: string;
	user: string;
	text: string;
	isBot: boolean;
}

/** A streaming feed's detail: recent transcript + the workspace/tenant needed to
 * deep-link out to the channel in Slack. `read_feed` returns both for a
 * streaming feed (`{ kind:'streaming', feed, messages }`). */
export interface ChannelFeedDetail {
	messages: ChannelFeedMessage[];
	/** Slack workspace/team id (`connections.external_tenant_id`), for the
	 * "Open in Slack" deep link. Null when the connection carries no team. */
	teamId: string | null;
}

/** Reads a streaming feed's recent transcript + its Slack team id from
 * `read_feed`. Only fetches when a feed id is set (the feed-detail deep link).
 * The transcript is membership-gated server-side, so a non-member sees none. */
export const useChannelFeed = createQuery<
	[feedId?: number | null],
	ChannelFeedDetail
>({
	queryKey: (feedId) => ["channel-feed", feedId],
	tool: "manage_feeds",
	body: (feedId) => ({ action: "read_feed", feed_id: feedId }),
	transform: (r) => ({
		messages: (r.messages ?? []) as ChannelFeedMessage[],
		teamId: (r.feed?.external_tenant_id ?? null) as string | null,
	}),
	enabled: (feedId) => !!feedId,
});

