const DEFAULT_TIMEOUT_MS = 10_000;

// Combine multiple AbortSignals into one. Prefers the platform `AbortSignal.any`
// (Node 20.3+, modern browsers, jsdom 23+) and falls back to a tiny shim for
// environments that haven't shipped it yet.
function composeSignals(signals: AbortSignal[]): AbortSignal {
  if (signals.length === 1) return signals[0];
  if (typeof (AbortSignal as unknown as { any?: typeof AbortSignal.any }).any === 'function') {
    return AbortSignal.any(signals);
  }
  const controller = new AbortController();
  for (const s of signals) {
    if (s.aborted) {
      controller.abort(s.reason);
      break;
    }
    s.addEventListener(
      'abort',
      () => {
        controller.abort(s.reason);
      },
      { once: true }
    );
  }
  return controller.signal;
}

export async function fetchWithTimeout(
  input: RequestInfo | URL,
  rawInit?: RequestInit & { timeoutMs?: number }
) {
  const init = withEmbeddedAuth(input, rawInit) as
    | (RequestInit & { timeoutMs?: number })
    | undefined;
  const timeoutMs = init?.timeoutMs ?? DEFAULT_TIMEOUT_MS;
  const timeoutController = new AbortController();
  const timeout = setTimeout(
    () =>
      timeoutController.abort(
        new DOMException(`Request timed out after ${timeoutMs}ms`, 'TimeoutError')
      ),
    timeoutMs
  );

  // Compose the caller's signal (if any) with our timeout signal so external
  // cancellation still works — the previous implementation silently overwrote
  // `init.signal`, breaking callers that wanted to cancel mid-flight.
  const signal = init?.signal
    ? composeSignals([init.signal, timeoutController.signal])
    : timeoutController.signal;

  try {
    const response = await fetch(input, {
      ...init,
      signal,
    });
    if (!response.ok) {
      captureApiError(input, response, init);
    }
    return response;
  } catch (error) {
    // Timeout-driven aborts are expected — don't report them.
    const isAbort =
      timeoutController.signal.aborted ||
      init?.signal?.aborted === true ||
      (error instanceof DOMException && error.name === 'AbortError') ||
      (error instanceof Error && error.name === 'AbortError');
    if (!isAbort) {
      captureApiException(input, error, init);
    }
    throw error;
  } finally {
    clearTimeout(timeout);
  }
}

