function inferenceProvidersUrl(orgSlug: string, path = "") {
	// Routes live inside the agents router, mounted at /api/:orgSlug/agents
	// (server index.ts: app.route("/api/:orgSlug/agents", agentRoutes)), so the
	// /agents/ segment stays even though these providers are org-scoped.
	return `${API_URL}/api/${orgSlug}/agents/inference-providers${path}`;
