/** GET /api/:org/inference-providers — org-owned providers (never the key). */
export function useInferenceProviders(options?: { enabled?: boolean }) {
	const { slug } = getPathScope();
	return useQuery({
		queryKey: ["inference-providers", slug],
		queryFn: async (): Promise<InferenceProviderItem[]> => {
			const res = await fetchWithTimeout(inferenceProvidersUrl(slug ?? ""), {
				credentials: "include",
			});
			await throwIfNotOk(res, "Failed to load inference providers");
			const data = (await res.json()) as InferenceProvidersPayload;
			return data.providers ?? [];
		},
		enabled: !!slug && (options?.enabled ?? true),
		staleTime: 30_000,
	});
}

