import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { createMemoryHistory, createRouter, RouterProvider } from '@tanstack/react-router';
import { render, type RenderResult } from '@testing-library/react';
import type { HttpHandler } from 'msw';
import type { ReactNode } from 'react';
import { GlobalNotFound } from '@/components/global-not-found';
import { setAuthStateMock } from './auth-state-mock';
import { server } from './msw-server';

// `__root.tsx` is module-mocked from `setup.ts` to a minimal `<Outlet />` so
// route smokes don't pull in the sidebar / SSE invalidator / better-auth-ui
// shell. Pages render their own component subtree on top of that empty root.

interface RenderRouteOptions {
  authenticated?: boolean;
  extraHandlers?: HttpHandler[];
}

interface RenderRouteResult extends RenderResult {
  queryClient: QueryClient;
}

export async function renderRoute(
  path: string,
  opts: RenderRouteOptions = {}
): Promise<RenderRouteResult> {
  const { authenticated = false, extraHandlers = [] } = opts;
  setAuthStateMock(authenticated ? 'authenticated' : 'anonymous');

  if (extraHandlers.length > 0) {
    server.use(...extraHandlers);
  }

  const queryClient = new QueryClient({
    defaultOptions: {
      queries: { retry: false, staleTime: Number.POSITIVE_INFINITY },
      mutations: { retry: false },
    },
  });

  // Import lazily so `vi.mock('@/app/__root', ...)` above lands first.
  const { routeTree } = await import('@/routeTree.gen');

  const history = createMemoryHistory({ initialEntries: [path] });
  const router = createRouter({
    routeTree,
    history,
    context: { queryClient },
    // Search-param parsing in the real router uses the URL form — keep defaults
    // so `validateSearch` on each route runs against an empty object.
    defaultPreload: false,
    // Mirror the real router (src/router.ts) so smokes of deleted legacy
    // paths exercise the same not-found surface production serves.
    defaultNotFoundComponent: GlobalNotFound,
  });

  const ui: ReactNode = (
    <QueryClientProvider client={queryClient}>
      {/** biome-ignore lint/suspicious/noExplicitAny: typed router casted for memory variant */}
      <RouterProvider router={router as any} />
    </QueryClientProvider>
  );

  const result = render(ui);
  return { ...result, queryClient };
}
