beforeAll(() => {
  // Fail loudly on any unmocked outbound request — that's the whole point.
  server.listen({ onUnhandledRequest: 'error' });
  server.events.on('request:start', ({ request }) => {
    if (process.env.MSW_DEBUG) {
      // biome-ignore lint/suspicious/noConsole: debug-only
      console.log('[MSW]', request.method, request.url);
    }
  });

  // jsdom installs its own AbortSignal on the global. @mswjs/interceptors
  // patches `globalThis.fetch` and runs `instanceof` against undici's own
  // AbortSignal — different class, so any app-issued `fetch(url, { signal })`
  // throws "Expected signal to be an instance of AbortSignal". We can't get
  // Node's primitives back into the jsdom realm cleanly (vm contexts don't
  // expose them; node:abort_controller doesn't exist). The pragmatic fix:
  // wrap MSW's patched fetch and strip the signal before it reaches undici.
  // We still honour aborts via Promise.race so callers see the same shape.
  //
  // This MUST run after `server.listen()` because that call is what installs
  // MSW's fetch wrapper.
  //
  // Notes on robustness (addressed in pi-review follow-up):
  //   - The abort listener is registered with `{ once: true }` and removed in
  //     a `finally` to avoid leaking listeners across tests on long-lived
  //     signals (e.g. shared AbortControllers in test fixtures).
  //   - `fetch(new Request(url, { signal }))` is now handled too — Request
  //     instances carry their own signal that bypasses `init.signal`.
  // biome-ignore lint/suspicious/noExplicitAny: jsdom shim
  const w = globalThis as any;
  const mswFetch: typeof fetch = w.fetch;
  w.fetch = function patchedFetch(input: RequestInfo | URL, init?: RequestInit) {
    // Request objects carry their own signal — pull it out so the same
    // race-based abort path applies to `fetch(new Request(url, { signal }))`.
    const requestSignal =
      typeof Request !== 'undefined' && input instanceof Request ? input.signal : null;
    const signal = init?.signal ?? requestSignal ?? null;

    if (signal) {
      const { signal: _stripped, ...rest } = init ?? {};
      let onAbort: (() => void) | null = null;
      const abortPromise = new Promise<Response>((_, reject) => {
        if (signal.aborted) {
          reject(new DOMException('Aborted', 'AbortError'));
          return;
        }
        onAbort = () => reject(new DOMException('Aborted', 'AbortError'));
        signal.addEventListener('abort', onAbort, { once: true });
      });
      const fetchPromise = mswFetch(input, rest);
      const race = Promise.race([fetchPromise, abortPromise]);
      // Detach the listener once either side settles so signals reused across
      // tests (or kept alive on long-lived fixtures) don't accumulate handlers.
      const cleanup = () => {
        if (onAbort) signal.removeEventListener('abort', onAbort);
      };
      race.then(cleanup, cleanup);
      return race;
    }
    return mswFetch(input, init);
  };
});

