  // The first mount in this file pays a one-time generated-route compile cost
  // under jsdom that can exceed Vitest's 5s default on a cold / loaded runner.
  it('redirects a zero-agent workspace root to Activity without resolving a system agent', async () => {
    let systemAgentRequests = 0;
    server.use(
      http.get('*/api/:slug/agents/system-agent', () => {
        systemAgentRequests += 1;
        return HttpResponse.json({ systemAgentId: 'lobu-builder' });
      })
    );
    const { router, unmount } = await mountAt('/test-org', true);
    await waitFor(() => expect(router.state.location.pathname).toBe('/test-org/activity'));
    expect(systemAgentRequests).toBe(0);
    unmount();
  }, 20_000);

  it('preserves peek state while dropping legacy home-chat search', async () => {
    const { router, unmount } = await mountAt(
