import { describe, expect, it } from "vitest";
import { renderRoute } from "@/test/render";

describe("managed agent creation route", () => {
	it("renders the create form for a workspace member", async () => {
		const { findByRole, unmount } = await renderRoute("/test-org/agents", {
			authenticated: true,
			extraHandlers: [
				http.get("*/api/organizations", () =>
					HttpResponse.json({
						organizations: [
							{
								id: "org-1",
								name: "Test Org",
								slug: "test-org",
								logo: null,
								description: null,
								created_at: "2026-01-01T00:00:00.000Z",
								is_member: true,
								visibility: "private",
							},
						],
					}),
				),
				http.get("*/api/:slug/agents", () => HttpResponse.json({ agents: [] })),
			],
		});

		expect(
			await findByRole("heading", { name: "Build a managed agent" }),
		).toBeInTheDocument();
		expect(await findByRole("button", { name: "Create agent" })).toBeDisabled();
		unmount();
	}, 30_000);

	it("refetches the complete agent before navigating to its Settings route", async () => {
		const previousUrl = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org/agents");
		const createdAgent = {
			agentId: "support-bot",
			name: "Support Bot",
			description: undefined,
			owner: { platform: "web", userId: "user-1" },
			createdAt: 1,
			connectionCount: 0,
			activeConnectionCount: 0,
			clientCount: 0,
			behaviorCount: 0,
			userCount: 1,
