/**
 * The agent create/edit form. Rendered inline inside an agent-detail tab
 * (one `section` per tab) or on the create page. One `<form>` / one save
 * covers Identity + Guardrails (they round-trip together);
 * Providers, Skills, and Reach self-save on dedicated routes.
 */
export function AgentEditorForm({
	mode,
	section = "identity",
	existingAgentIds = [],
	onCreated,
	onCancel,
	onDone,
	reviewMode = "none",
	reviewProposal = null,
	reviewControlsDisabled = false,
}: {
	mode: AgentEditorMode;
	section?: AgentSection;
	existingAgentIds?: string[];
	onCreated?: (agentId: string) => void | Promise<void>;
	onCancel?: () => void;
	/** Called after a successful save/delete (and after create if no onCreated). */
	onDone?: () => void;
	/** Config-approval review state, supplied by the wrapping {@link ProposalReviewShell}
	 *  (Slack deep link `?run_id`). The shell owns the fetch + lifecycle + Approve/
	 *  Reject footer; this form only PREFILLS the proposed values (read-only) and
	 *  hides its own Save/Delete footer during an active review. Defaults ⇒ normal
	 *  edit (no review). */
	reviewMode?: ReviewMode;
	/** The held proposal to overlay when reviewMode is active; null otherwise. */
	reviewProposal?: PendingProposal | null;
	/** True when the shell says editable controls must be locked (fail-closed). */
	reviewControlsDisabled?: boolean;
}) {
	const isCreate = mode.kind === "create";
	const selectedAgent = mode.kind === "edit" ? mode.agent : null;
	const needsConfigEditorData =
		!isCreate &&
		section !== "platforms" &&
		section !== "skills" &&
		!!selectedAgent;
	const createAgent = useCreateAgent();
	const updateAgent = useUpdateAgent(selectedAgent?.agentId ?? "");
	const deleteAgent = useDeleteAgent(selectedAgent?.agentId ?? "");
	const updateAgentConfig = useUpdateAgentConfig(selectedAgent?.agentId ?? "");
	const { data: agentConfig, isLoading: isConfigLoading } = useAgentConfig(
		selectedAgent?.agentId,
		{ enabled: needsConfigEditorData },
	);

	// Review state is owned by the wrapping ProposalReviewShell and threaded in as
	// props; this form only consumes it to prefill + lock. `create` is never a
	// review (no agent to change), so ignore any review props then.
	const reviewActive = !isCreate && reviewMode === "active";
	const pendingProposal = reviewActive ? reviewProposal : null;

	// Callers remount this form (key on the agent id, or 'create') when the
	// target changes, so initial state can come straight from `mode` and the
	// async-loaded config below.
	const [name, setName] = useState(() =>
		mode.kind === "edit" ? mode.agent.name : "",
	);
	const [description, setDescription] = useState(() =>
		mode.kind === "edit" ? (mode.agent.description ?? "") : "",
	);
	const [identityMd, setIdentityMd] = useState("");
	const [soulMd, setSoulMd] = useState("");
	const [userMd, setUserMd] = useState("");
	const [models, setModels] = useState<string[]>([]);
	const [showToolCalls, setShowToolCalls] = useState(false);
	const [sandboxId, setSandboxId] = useState<string>("builtin");
	const [confirmingDeleteAgent, setConfirmingDeleteAgent] = useState(false);

	const { data: sandboxesData } = useSandboxes({
		enabled: section === "models" && !isCreate,
	});

	useEffect(() => {
		if (!selectedAgent || !agentConfig) return;
		setIdentityMd(agentConfig.identityMd ?? "");
		setSoulMd(agentConfig.soulMd ?? "");
		setUserMd(agentConfig.userMd ?? "");
		setModels(
			(agentConfig as { models?: string[] }).models ??
				(agentConfig as { settings?: { models?: string[] } }).settings
					?.models ??
				[],
		);
		// Config returns it flat; the resolved shape nests under `settings`.
		setShowToolCalls(
			(agentConfig as { showToolCalls?: boolean }).showToolCalls ??
				(agentConfig as { settings?: { showToolCalls?: boolean } }).settings
					?.showToolCalls ??
				false,
		);
		setSandboxId(
			(agentConfig as { sandboxId?: string | null }).sandboxId ??
				(agentConfig as { settings?: { sandboxId?: string | null } }).settings
					?.sandboxId ??
				"builtin",
		);

		// Config-approval review: overlay the held proposal ON TOP of the just-
		// hydrated config, in the SAME effect so the base values can never clobber
		// the proposed ones (single write, no cross-effect race). Only keys the
		// proposal carries are overlaid; the rest keep their server values.
		if (pendingProposal) {
			const overlay = overlayFromProposal(pendingProposal.proposal);
			if (overlay.name !== undefined) setName(overlay.name);
			if (overlay.description !== undefined)
				setDescription(overlay.description);
			if (overlay.identityMd !== undefined) setIdentityMd(overlay.identityMd);
		}
	}, [agentConfig, selectedAgent, pendingProposal]);

	const handleSubmit = useCallback(
		async (event: React.FormEvent) => {
			event.preventDefault();

			if (isCreate) {
				const created = await createAgent.mutateAsync({
					agentId: buildGeneratedAgentId(name, existingAgentIds),
					name: name.trim(),
					description: description.trim() || undefined,
				});
				if (onCreated) {
					await onCreated(created.agentId);
				} else {
					onDone?.();
				}
				return;
			}

			if (!selectedAgent) return;
			// Guard the race where the form is submitted before the agent config
			// has loaded — local rows would still be empty and would wipe identity,
			// providers, and skills on the server. Only `agentConfig` is required:
			// the provider/skill/guardrail catalogs are display-only enrichment for
			// the "add" pickers (the row builders preserve the agent's own config
			// without them), so they must NOT gate saving — an unavailable or slow
			// catalog would otherwise silently block every section's save.
			if (!agentConfig) {
				toast.error("Still loading agent settings — try again in a moment");
				return;
			}

			try {
				await Promise.all([
					updateAgent.mutateAsync({
						name: name.trim() || selectedAgent.name,
						description: description.trim() || undefined,
					}),
					updateAgentConfig.mutateAsync({
						identityMd: identityMd.trim(),
						soulMd: soulMd.trim(),
						userMd: userMd.trim(),
						models,
	 * item can span more than one stage — e.g. `pii-scan` runs at input,
	 * output, and pre-tool.
	 */
	stages: GuardrailStage[];
	description?: string;
}

