		expect(screen.queryByRole("link", { name: "ChatGPT" })).toBeNull();
		expect(screen.queryByRole("link", { name: "Claude Desktop" })).toBeNull();
		expect(screen.queryByRole("link", { name: "Cursor" })).toBeNull();
		expect(screen.queryByRole("link", { name: "U123" })).toBeNull();
	});

	it("keeps the agent roster app-free on connected app detail routes", async () => {
		await renderSidebarAt(
			"/test-org/connectors/client/chatgpt-client-older-registration",
		);

		expect(screen.queryByRole("link", { name: "ChatGPT" })).toBeNull();
		expect(screen.queryByRole("link", { name: "Claude Desktop" })).toBeNull();
	});

	it("offers connect and build actions when the workspace has no agents", async () => {
