			"href",
			"/test-org/connectors/client/claude-desktop-client?activity=claude-conversation",
		);
		expect(claudeRow).not.toHaveAttribute("title");
		expect(screen.getByText(/Search memory · .* ago/)).toBeInTheDocument();
		expect(
			claudeRow?.querySelector('[data-app-icon="anthropic"]'),
		).not.toBeNull();

		const chatgptLink = screen.getByRole("link", {
			name: "ChatGPT conversation",
		});
