import { useQueryClient } from "@tanstack/react-query";
import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { AgentEditorForm } from "@/components/agents/agent-editor-form";
import { useCurrentOrg } from "@/hooks/use-current-org";
import { useAgents } from "@/lib/api";
import { useAuthState } from "@/lib/auth-state";

export const Route = createFileRoute("/$owner/agents/")({
	component: NewAgentPage,
});

function NewAgentPage() {
	const { owner } = Route.useParams();
	const navigate = useNavigate();
	const queryClient = useQueryClient();
	const { isAuthenticated } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: canManageWorkspace,
	});

	if (isOrgLoading || !canManageWorkspace || isAgentsLoading) return null;

	return (
		<div className="mx-auto flex w-full max-w-2xl flex-1 flex-col px-4 py-8 lg:px-6">
			<div className="mb-6">
				<h1 className="text-xl font-semibold tracking-tight">
					Build a managed agent
				</h1>
				<p className="mt-1 text-sm text-muted-foreground">
					Create an agent that Lobu runs and manages for this workspace.
				</p>
			</div>
			<AgentEditorForm
				mode={{ kind: "create" }}
				existingAgentIds={agents.map((agent) => agent.agentId)}
				onCreated={async (agentId) => {
					const queryKey = ["agents", owner] as const;
					await queryClient.refetchQueries({ queryKey, exact: true });
					await navigate({
						to: "/$owner/agents/$agentId/settings",
						params: { owner, agentId },
						search: { run_id: undefined },
					});
				}}
			/>
		</div>
	);
}
import { fireEvent, waitFor } from "@testing-library/react";
import { HttpResponse, http } from "msw";
import { describe, expect, it } from "vitest";
import { renderRoute } from "@/test/render";

describe("managed agent creation route", () => {
	it("renders the create form for a workspace member", async () => {
		const { findByRole, unmount } = await renderRoute("/test-org/agents", {
			authenticated: true,
			extraHandlers: [
				http.get("*/api/organizations", () =>
					HttpResponse.json({
						organizations: [
							{
								id: "org-1",
								name: "Test Org",
								slug: "test-org",
								logo: null,
								description: null,
								created_at: "2026-01-01T00:00:00.000Z",
								is_member: true,
								visibility: "private",
							},
						],
					}),
				),
				http.get("*/api/:slug/agents", () => HttpResponse.json({ agents: [] })),
			],
		});

		expect(
			await findByRole("heading", { name: "Build a managed agent" }),
		).toBeInTheDocument();
		expect(await findByRole("button", { name: "Create agent" })).toBeDisabled();
		unmount();
	}, 30_000);

	it("refetches the complete agent before navigating to its Settings route", async () => {
		const previousUrl = window.location.pathname + window.location.search;
		window.history.replaceState({}, "", "/test-org/agents");
		const createdAgent = {
			agentId: "support-bot",
			name: "Support Bot",
			description: undefined,
			owner: { platform: "web", userId: "user-1" },
			createdAt: 1,
			connectionCount: 0,
			activeConnectionCount: 0,
			clientCount: 0,
			behaviorCount: 0,
			userCount: 1,
			platforms: [],
			providers: [],
			status: "idle" as const,
			settings: {},
		};
		let agentCreated = false;
		let unmount: (() => void) | undefined;
		try {
			const result = await renderRoute("/test-org/agents", {
				authenticated: true,
				extraHandlers: [
					http.get("*/api/organizations", () =>
						HttpResponse.json({
							organizations: [
								{
									id: "org-1",
									name: "Test Org",
									slug: "test-org",
									logo: null,
									description: null,
									created_at: "2026-01-01T00:00:00.000Z",
									is_member: true,
									visibility: "private",
								},
							],
						}),
					),
					http.get("*/api/:slug/agents", async () => {
						if (!agentCreated) return HttpResponse.json({ agents: [] });
						await new Promise((resolve) => setTimeout(resolve, 50));
						return HttpResponse.json({ agents: [createdAgent] });
					}),
					http.post("*/api/:slug/agents", () => {
						agentCreated = true;
						return HttpResponse.json({
							agentId: createdAgent.agentId,
							name: createdAgent.name,
							description: createdAgent.description,
						});
					}),
					http.get("*/api/:slug/agents/:agentId/config", () =>
						HttpResponse.json(createdAgent.settings),
					),
				],
			});
			unmount = result.unmount;

			fireEvent.change(await result.findByLabelText(/^Name/), {
				target: { value: "Support Bot" },
			});
			fireEvent.click(
				await result.findByRole("button", { name: "Create agent" }),
			);

			await waitFor(() =>
				expect(result.queryClient.getQueryData(["agents", "test-org"])).toEqual(
					[
						expect.objectContaining({
							agentId: "support-bot",
							name: "Support Bot",
							status: "idle",
							platforms: [],
						}),
					],
				),
			);
			expect(
				await result.findByRole("heading", { name: "Support Bot" }),
			).toBeInTheDocument();
			expect(
				await result.findByRole("button", { name: "Delete agent" }),
			).toBeInTheDocument();
		} finally {
			unmount?.();
			window.history.replaceState({}, "", previousUrl);
		}
	}, 30_000);
});
"}

