import { buildGeneratedAgentId } from "@/components/agents/agent-id-utils";

describe("buildGeneratedAgentId", () => {
	it("prefixes one- and two-character slugs to satisfy the server minimum", () => {
		expect(buildGeneratedAgentId("A", [])).toBe("agent-a");
		expect(buildGeneratedAgentId("AI", [])).toBe("agent-ai");
	});

	it("keeps generated collision suffixes within the server maximum", () => {
		const sixtyCharacters = "a".repeat(60);
		expect(buildGeneratedAgentId(sixtyCharacters, [sixtyCharacters])).toBe(
			`${"a".repeat(58)}-2`,
		);
	});
});

