			: typeof searchRecord.entity === "string"
				? searchRecord.entity.split("/")[0]
				: undefined;

	// The row keeps the highlight while the map itself is what is open; once a
	// child type is being browsed, the type's own row carries it instead.
	const isHighlighted = active && !(open && activeTypeSlug);

	return (
