}

function parentCommentBody(
  state: "pending" | "success",
  proof: UiReviewProof,
  proofUrl: string,
  approvalUrl: string | null,
  lobuHead: string
): string {
  const headline =
    state === "success" ? "UI review approved" : "UI review awaiting approval";
  const approvalLine = approvalUrl
    ? `- Approval: ${approvalUrl}`
