export const Route = createFileRoute("/$owner/agents/")({
	component: NewAgentPage,
});

function NewAgentPage() {
	const { owner } = Route.useParams();
	const navigate = useNavigate();
	const queryClient = useQueryClient();
	const { isAuthenticated } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const canManageWorkspace = isAuthenticated && isMember;
	const { data: agents = [], isLoading: isAgentsLoading } = useAgents({
		enabled: canManageWorkspace,
	});

	return (
		<div className="mx-auto flex w-full max-w-2xl flex-1 flex-col px-4 py-8 lg:px-6">
			<div className="mb-6">
				<h1 className="text-xl font-semibold tracking-tight">
					Build a managed agent
				</h1>
				<p className="mt-1 text-sm text-muted-foreground">
					Create an agent that Lobu runs and manages for this workspace.
				</p>
			</div>
			{isOrgLoading || (canManageWorkspace && isAgentsLoading) ? (
				<FormLoadingShell rows={1} />
			) : !canManageWorkspace ? (
				<TabEmptyState
					icon={Lock}
					title="Workspace membership required"
					description="Only workspace members can build managed agents."
				/>
			) : (
				<AgentEditorForm
					mode={{ kind: "create" }}
					existingAgentIds={agents.map((agent) => agent.agentId)}
					onCreated={async (agentId) => {
						const queryKey = ["agents", owner] as const;
						await queryClient.refetchQueries({ queryKey, exact: true });
						await navigate({
							to: "/$owner/agents/$agentId/settings",
							params: { owner, agentId },
							search: { run_id: undefined },
						});
					}}
				/>
			)}
		</div>
	);
}
