const cmds=[
  ["checks","gh pr checks 2481 --required || true"],
  ["status","gh api repos/lobu-ai/lobu/commits/45f2a7a0a49d0a0344b56801abeeacb8eca4d248/status --jq '{state:.state,statuses:[.statuses[]|{context,state,description,target_url}]}'"],
  ["comments","gh api repos/lobu-ai/owletto/issues/714/comments --jq '.[-3:] | map({user:.user.login,created_at,body})'"],
  ["local","curl -sS -H 'Accept: text/html' -o /dev/null -w 'dev_root=%{http_code}\\n' http://localhost:9283/\ncurl -sS -H 'Accept: text/html' -o /dev/null -w 'dev_activity=%{http_code}\\n' http://localhost:9283/sidebar-agents-empty/activity\ngit status --short\ngit diff --stat origin/main...HEAD"]
];
const rs=await Promise.all(cmds.map(async ([k,cmd])=>[k,await tools.exec_command({cmd,workdir:wd,yield_time_ms:1000,max_output_tokens:3000})]));
for(const [k,r] of rs){text(`==${k}==\n${r.output}`)}
